// SPDX-License-Identifier: Apache-2.0
// specs/memory/notebooklm.t27
// NotebookLM Integration Specification
// Ring-071 - RAG-Backed Semantic Memory for t27
// Defines interface to Google NotebookLM for persistent session memory
// phi^2 + 1/phi^2 = 3 | TRINITY

module NotebookLM {
    // ====================================================================
    // 1. Constants
    // ====================================================================

    const VERSION : u32 = 1;
    const DEFAULT_TIMEOUT_MS : u32 = 30000;
    const MAX_SOURCE_SIZE : u32 = 10485760; // 10MB
    const DEFAULT_NOTEBOOK_NAME : str = "t27-QUEEN-BRAIN";

    const AUTH_STATE_UNAUTHENTICATED : u8 = 0;
    const AUTH_STATE_AUTHENTICATED : u8 = 1;
    const AUTH_STATE_EXPIRED : u8 = 2;
    const AUTH_STATE_REFRESHING : u8 = 3;

    const CONNECTION_STATUS_DISCONNECTED : u8 = 0;
    const CONNECTION_STATUS_CONNECTING : u8 = 1;
    const CONNECTION_STATUS_CONNECTED : u8 = 2;
    const CONNECTION_STATUS_ERROR : u8 = 3;

    // ====================================================================
    // 2. Error Codes
    // ====================================================================

    enum ErrorCode {
        Success = 0,
        AuthenticationFailed = 1,
        NetworkError = 2,
        Timeout = 3,
        InvalidInput = 4,
        SourceNotFound = 5,
        NotebookNotFound = 6,
        RateLimited = 7,
        StorageError = 8,
        ConfigurationError = 9,
        UnknownError = 99,
    }

    // ====================================================================
    // 3. Authentication Types
    // ====================================================================

    struct AuthTokens {
        cookie_header: str,
        csrf_token: str,
        session_id: str,
        expires_at: u64, // Unix timestamp
    }

    struct NotebookLMConfig {
        storage_path: str,
        notebook_name: str,
        timeout_ms: u32,
        auto_refresh: bool,
    }

    // ====================================================================
    // 4. NotebookLM Client
    // ====================================================================

    struct NotebookLMClient {
        config: NotebookLMConfig,
        auth_state: u8,
        connection_status: u8,
        auth: AuthTokens,
    }

    // ====================================================================
    // 5. Notebook Types
    // ====================================================================

    struct Notebook {
        id: str,
        title: str,
        created_at: u64,
        updated_at: u64,
        source_count: usize,
    }

    struct Source {
        id: str,
        notebook_id: str,
        title: str,
        source_type: str, // "text", "url", "file", "youtube"
        status: str, // "processing", "ready", "error"
        created_at: u64,
    }

    // ====================================================================
    // 6. Query and Result Types
    // ====================================================================

    struct QueryResult {
        notebook_id: str,
        query: str,
        answer: str,
        sources: [5]str, // Up to 5 relevant sources
        confidence: f64,
        timestamp: u64,
    }

    // ====================================================================
    // 7. Session Context Types
    // ====================================================================

    struct SessionContext {
        session_id: str,
        repo_root: str,
        branch: str,
        skill_id: str,
        issue_number: usize,
        start_time: u64,
        tasks_completed: usize,
        files_modified: usize,
        git_status: str,
    }

    // ====================================================================
    // 8. Wrap-up Types
    // ====================================================================

    struct WrapupSummary {
        session: SessionContext,
        summary: str,
        key_decisions: str,
        files_changed: str,
        next_steps: str,
        created_at: u64,
    }

    struct MemoryEntry {
        entry_id: str,
        session_id: str,
        notebook_id: str,
        source_id: str,
        wrapup: WrapupSummary,
        indexed_at: u64,
    }

    // ====================================================================
    // 9. Client Functions
    // ====================================================================

    // client_new(config: NotebookLMConfig) -> NotebookLMClient
    // Create a new NotebookLM client with given configuration
    fn client_new(config: NotebookLMConfig) -> NotebookLMClient {
        var client : NotebookLMClient = undefined;
        client.config = config;
        client.auth_state = AUTH_STATE_UNAUTHENTICATED;
        client.connection_status = CONNECTION_STATUS_DISCONNECTED;
        return client;
    }

    // client_authenticate(client: NotebookLMClient) -> ErrorCode
    // Authenticate the client using stored cookies
    fn client_authenticate(client: *NotebookLMClient) -> ErrorCode {
        // Implementation: loads auth from storage_path
        // Returns Success if authenticated, AuthFailed otherwise
        return ErrorCode::Success;
    }

    // client_is_authenticated(client: NotebookLMClient) -> bool
    // Check if client is authenticated
    fn client_is_authenticated(client: NotebookLMClient) -> bool {
        return client.auth_state == AUTH_STATE_AUTHENTICATED;
    }

    // client_close(client: NotebookLMClient) -> ErrorCode
    // Close the client connection
    fn client_close(client: *NotebookLMClient) -> ErrorCode {
        client.connection_status = CONNECTION_STATUS_DISCONNECTED;
        return ErrorCode::Success;
    }

    // ====================================================================
    // 10. Notebook Functions
    // ====================================================================

    // notebook_create(client: NotebookLMClient, title: str) -> (Notebook, ErrorCode)
    // Create a new notebook
    fn notebook_create(client: NotebookLMClient, title: str) -> (Notebook, ErrorCode) {
        var notebook : Notebook = undefined;
        return (notebook, ErrorCode::Success);
    }

    // notebook_list(client: NotebookLMClient) -> ([]Notebook, ErrorCode)
    // List all notebooks
    fn notebook_list(client: NotebookLMClient) -> ([]Notebook, ErrorCode) {
        var notebooks : [0]Notebook = undefined;
        return (notebooks, ErrorCode::Success);
    }

    // notebook_get(client: NotebookLMClient, notebook_id: str) -> (Notebook, ErrorCode)
    // Get a specific notebook by ID
    fn notebook_get(client: NotebookLMClient, notebook_id: str) -> (Notebook, ErrorCode) {
        var notebook : Notebook = undefined;
        return (notebook, ErrorCode::Success);
    }

    // notebook_find_by_name(client: NotebookLMClient, name: str) -> (Notebook, ErrorCode)
    // Find a notebook by title, returns NotebookNotFound if not found
    fn notebook_find_by_name(client: NotebookLMClient, name: str) -> (Notebook, ErrorCode) {
        var notebook : Notebook = undefined;
        return (notebook, ErrorCode::NotebookNotFound);
    }

    // notebook_delete(client: NotebookLMClient, notebook_id: str) -> ErrorCode
    // Delete a notebook
    fn notebook_delete(client: NotebookLMClient, notebook_id: str) -> ErrorCode {
        return ErrorCode::Success;
    }

    // ====================================================================
    // 11. Source Functions
    // ====================================================================

    // source_upload_text(client: NotebookLMClient, notebook_id: str, title: str, content: str) -> (Source, ErrorCode)
    // Upload text content as a source
    fn source_upload_text(client: NotebookLMClient, notebook_id: str, title: str, content: str) -> (Source, ErrorCode) {
        var source : Source = undefined;
        return (source, ErrorCode::Success);
    }

    // source_upload_file(client: NotebookLMClient, notebook_id: str, file_path: str) -> (Source, ErrorCode)
    // Upload a file as a source
    fn source_upload_file(client: NotebookLMClient, notebook_id: str, file_path: str) -> (Source, ErrorCode) {
        var source : Source = undefined;
        return (source, ErrorCode::Success);
    }

    // source_list(client: NotebookLMClient, notebook_id: str) -> ([]Source, ErrorCode)
    // List all sources in a notebook
    fn source_list(client: NotebookLMClient, notebook_id: str) -> ([]Source, ErrorCode) {
        var sources : [0]Source = undefined;
        return (sources, ErrorCode::Success);
    }

    // source_delete(client: NotebookLMClient, source_id: str) -> ErrorCode
    // Delete a source
    fn source_delete(client: NotebookLMClient, source_id: str) -> ErrorCode {
        return ErrorCode::Success;
    }

    // ====================================================================
    // 12. Query Functions
    // ====================================================================

    // notebook_query(client: NotebookLMClient, notebook_id: str, question: str) -> (QueryResult, ErrorCode)
    // Query a notebook with a question
    fn notebook_query(client: NotebookLMClient, notebook_id: str, question: str) -> (QueryResult, ErrorCode) {
        var result : QueryResult = undefined;
        return (result, ErrorCode::Success);
    }

    // ====================================================================
    // 13. Session Functions
    // ====================================================================

    // session_extract_from_trinity(repo_root: str) -> (SessionContext, ErrorCode)
    // Extract session context from .trinity state files
    fn session_extract_from_trinity(repo_root: str) -> (SessionContext, ErrorCode) {
        var context : SessionContext = undefined;
        return (context, ErrorCode::Success);
    }

    // ====================================================================
    // 14. Wrap-up Functions
    // ====================================================================

    // wrapup_format_summary(session: SessionContext, summary: str, decisions: str, files: str, steps: str) -> WrapupSummary
    // Format a wrap-up summary from session data
    fn wrapup_format_summary(session: SessionContext, summary: str, decisions: str, files: str, steps: str) -> WrapupSummary {
        var wrapup : WrapupSummary = undefined;
        wrapup.session = session;
        wrapup.summary = summary;
        wrapup.key_decisions = decisions;
        wrapup.files_changed = files;
        wrapup.next_steps = steps;
        wrapup.created_at = 0; // Set to current time
        return wrapup;
    }

    // wrapup_upload(client: NotebookLMClient, wrapup: WrapupSummary, notebook_id: str) -> (Source, ErrorCode)
    // Upload a wrap-up summary to NotebookLM
    fn wrapup_upload(client: NotebookLMClient, wrapup: WrapupSummary, notebook_id: str) -> (Source, ErrorCode) {
        var source : Source = undefined;
        return (source, ErrorCode::Success);
    }

    // ====================================================================
    // 15. TDD - Tests
    // ====================================================================

    test "client_creation"
        var config : NotebookLMConfig = undefined;
        config.storage_path = "/tmp/notebooklm";
        config.notebook_name = DEFAULT_NOTEBOOK_NAME;
        config.timeout_ms = DEFAULT_TIMEOUT_MS;
        config.auto_refresh = true;

        const client = client_new(config);
        assert(client.auth_state == AUTH_STATE_UNAUTHENTICATED);
        assert(client.connection_status == CONNECTION_STATUS_DISCONNECTED);
        assert(ErrorCode::Success == ErrorCode::Success);

    test "client_lifecycle"
        var config : NotebookLMConfig = undefined;
        config.storage_path = "/tmp/notebooklm";
        config.notebook_name = DEFAULT_NOTEBOOK_NAME;
        config.timeout_ms = DEFAULT_TIMEOUT_MS;
        config.auto_refresh = false;

        var client = client_new(config);
        const auth_result = client_authenticate(&client);
        const close_result = client_close(&client);
        assert(close_result == ErrorCode::Success);

    test "client_is_authenticated_unauthenticated"
        var config : NotebookLMConfig = undefined;
        var client = client_new(config);
        const is_auth = client_is_authenticated(client);
        assert(is_auth == false);

    test "constants_defined"
        assert(VERSION == 1);
        assert(DEFAULT_TIMEOUT_MS == 30000);
        assert(MAX_SOURCE_SIZE == 10485760);
        assert(DEFAULT_NOTEBOOK_NAME == "t27-QUEEN-BRAIN");

    test "error_codes_unique"
        assert(ErrorCode::Success == 0);
        assert(ErrorCode::AuthenticationFailed == 1);
        assert(ErrorCode::NetworkError == 2);
        assert(ErrorCode::Timeout == 3);
        assert(ErrorCode::InvalidInput == 4);
        assert(ErrorCode::SourceNotFound == 5);
        assert(ErrorCode::NotebookNotFound == 6);

    test "notebook_find_by_name_not_found"
        var config : NotebookLMConfig = undefined;
        var client = client_new(config);
        const (notebook, err) = notebook_find_by_name(client, "nonexistent");
        assert(err == ErrorCode::NotebookNotFound);

    test "source_upload_text_size_limit"
        var config : NotebookLMConfig = undefined;
        var client = client_new(config);
        var large_content : [MAX_SOURCE_SIZE + 1]u8 = undefined;
        const (source, err) = source_upload_text(client, "nb-id", "title", large_content);
        // Should fail with InvalidInput for too large content
        assert(err == ErrorCode::InvalidInput);

    test "notebook_query_returns_result"
        var config : NotebookLMConfig = undefined;
        var client = client_new(config);
        const (result, err) = notebook_query(client, "nb-id", "test question");
        assert(err == ErrorCode::Success);
        assert(result.confidence >= 0.0);
        assert(result.confidence <= 1.0);

    test "session_extract_from_trinity"
        const (context, err) = session_extract_from_trinity("/tmp/repo");
        assert(err == ErrorCode::Success);

    test "wrapup_format_summary"
        var session : SessionContext = undefined;
        session.session_id = "test-session";
        session.branch = "main";
        session.skill_id = "test-skill";

        const wrapup = wrapup_format_summary(session, "summary", "decisions", "files", "steps");
        assert(wrapup.session.session_id == "test-session");
        assert(wrapup.summary == "summary");

    // ====================================================================
    // 16. TDD - Invariants
    // ====================================================================

    invariant confidence_always_valid
        var config : NotebookLMConfig = undefined;
        var client = client_new(config);
        const (result, err) = notebook_query(client, "nb-id", "test");
        assert(result.confidence >= 0.0);
        assert(result.confidence <= 1.0);

    invariant auth_state_transitions_valid
        var config : NotebookLMConfig = undefined;
        var client = client_new(config);
        // Initial state is unauthenticated
        assert(client.auth_state == AUTH_STATE_UNAUTHENTICATED);
        // After auth, should be authenticated
        _ = client_authenticate(&client);
        // Auth state is tracked internally

    invariant max_source_size_positive
        assert(MAX_SOURCE_SIZE > 0);
        assert(MAX_SOURCE_SIZE == 10485760); // 10MB

    invariant timeout_must_be_positive
        assert(DEFAULT_TIMEOUT_MS > 0);

    invariant notebook_name_not_empty
        assert(DEFAULT_NOTEBOOK_NAME.len > 0);

    invariant wrapup_preserves_session
        var session : SessionContext = undefined;
        session.session_id = "original-session";
        session.skill_id = "original-skill";
        const wrapup = wrapup_format_summary(session, "", "", "", "");
        assert(wrapup.session.session_id == "original-session");
        assert(wrapup.session.skill_id == "original-skill");

    invariant error_codes_positive
        // All non-success error codes should be positive
        assert(ErrorCode::Success == 0);
        assert(ErrorCode::AuthenticationFailed > 0);
        assert(ErrorCode::NetworkError > 0);
        assert(ErrorCode::Timeout > 0);
        assert(ErrorCode::InvalidInput > 0);
        assert(ErrorCode::SourceNotFound > 0);
        assert(ErrorCode::NotebookNotFound > 0);

    // ====================================================================
    // 17. TDD - Benchmarks
    // ====================================================================

    bench client_creation_bench
        // Target: < 1000 cycles
        var config : NotebookLMConfig = undefined;
        config.storage_path = "/tmp/notebooklm";
        config.notebook_name = DEFAULT_NOTEBOOK_NAME;
        config.timeout_ms = DEFAULT_TIMEOUT_MS;
        config.auto_refresh = true;

        @setEvalBranchQuota(10000);
        var client : NotebookLMClient = undefined;
        for (0..100) |_| {
            client = client_new(config);
        }
        _ = client;

    bench wrapup_format_summary_bench
        // Target: < 2000 cycles
        var session : SessionContext = undefined;
        session.session_id = "bench-session";
        session.branch = "main";
        session.skill_id = "bench-skill";

        const summary = "Test summary content";
        const decisions = "Test decisions";
        const files = "Test files";
        const steps = "Test steps";

        @setEvalBranchQuota(10000);
        var wrapup : WrapupSummary = undefined;
        for (0..100) |_| {
            wrapup = wrapup_format_summary(session, summary, decisions, files, steps);
        }
        _ = wrapup;

    bench error_code_comparison_bench
        // Target: < 500 cycles
        @setEvalBranchQuota(10000);
        var result : bool = false;
        for (0..1000) |_| {
            result = ErrorCode::Success == ErrorCode::Success;
        }
        _ = result;

    bench constant_access_bench
        // Target: < 100 cycles
        @setEvalBranchQuota(10000);
        var result : u32 = 0;
        for (0..1000) |_| {
            result = DEFAULT_TIMEOUT_MS;
        }
        _ = result;
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/numeric/gf8.t27
// GoldenFloat8 -- 8-bit phi-structured floating point
// NUMERIC-STANDARD-001 -- Agent 3 (P1)

module GF8 {
    // Import base format family
    use numeric::goldenfloat_family;
    use numeric::phi_ratio;

    // Import test/invariant/bench framework
    use base::testing;
    use base::benchmarking;

    // =================================================================
    // 1. Format Definition
    // =========================================================================

    // GF8 bit layout: [S|EEE|MMMM]
    //   S: 1 bit  (sign)
    //   E: 3 bits (exponent)
    //   M: 4 bits (mantissa)

    const BITS : u8 = 8;
    const SIGN_BITS : u8 = 1;
    const EXP_BITS : u8 = 3;
    const MANT_BITS : u8 = 4;

    // Bias for exponent (2^(3-1) - 1 = 3)
    const EXP_BIAS : u8 = 3;

    // phi-ratio: exp/mant = 3/4 = 0.75
    // phi-distance: math::constants::PHI_DISTANCE
    const PHI_DISTANCE : f64 = 0.132;

    // =================================================================
    // 2. GoldenFloat8 Type
    // =========================================================================

    struct GF8 {
        raw : u8,  // 8-bit raw value
    }

    // =================================================================
    // 3. Encoding/Decoding
    // =========================================================================

    // Encode f32 to GF8
    fn encode(value: f32) -> GF8 {
        if (value == 0.0) {
            return GF8{ raw = 0 };
        }

        const sign = if (value < 0.0) { 1 } else { 0 };
        const abs_val = if (value < 0.0) { -value } else { value };

        // Extract exponent (unbiased)
        const exp_unbiased = floor_log2(abs_val) as i8;
        const exp_biased = (exp_unbiased + EXP_BIAS as i8) as u8;

        // Clamp exponent
        const exp_clamped = clamp(exp_biased, 0, (1 << EXP_BITS) - 1);

        // Extract mantissa (4 bits)
        const mant = extract_mantissa(abs_val, exp_unbiased, MANT_BITS);

        return GF8{
            raw = (sign << 7) | (exp_clamped << MANT_BITS) | mant
        };
    }

    // Test: gf8_phi_distance invariant
    test gf8_phi_distance
        given phi = 1.618033988749894848 // math::sacred_physics::PHI
        when  gf8_phi = GF8::encode(phi)
        then  gf8_phi.raw == 0b01000000 // |S|EEE (phi = math::constants::PHI_DISTANCE)

    // Decode GF8 to f32
    fn decode(gf: GF8) -> f32 {
        const sign = (gf.raw >> 7) as u8;
        const exp_biased = ((gf.raw >> MANT_BITS) & 0x07) as u8;
        const mant = (gf.raw & 0x0F) as u8;

        // Zero
        if (exp_biased == 0 && mant == 0) {
            return 0.0;
        }

        // Exponent (with special case for subnormals)
        const exp_unbiased = if (exp_biased == 0) {
            -EXP_BIAS as i8 + 1
        } else {
            (exp_biased as i8) - EXP_BIAS as i8
        };

        // Mantissa (with implicit 1 for normalized, 0 for subnormal)
        const mant_normalized = if (exp_biased == 0) {
            (mant as f32) / 16.0
        } else {
            1.0 + (mant as f32) / 16.0
        };

        const value = mant_normalized * pow(2.0, exp_unbiased as f32);

        if (sign != 0) {
            return -value;
        }
        return value;
    }

    // =================================================================
    // 4. Format Properties
    // =========================================================================

    fn max_value() -> f32 {
        // Max normalized: mant=1.9375, exp=3 -> 15.5
        const mant_max = 1.0 + 15.0 / 16.0;
        const exp_max = (1 << EXP_BITS) - 1 - EXP_BIAS;
        return mant_max * pow(2.0, exp_max as f32);
    }

    fn min_positive() -> f32 {
        // Min subnormal: mant=1/16, exp=-2 -> 0.0625
        const mant_min = 1.0 / 16.0;
        const exp_min = -EXP_BIAS as i8 + 1;
        return mant_min * pow(2.0, exp_min as f32);
    }

    fn epsilon() -> f32 {
        // Smallest representable difference at 1.0
        return 1.0 / 16.0;  // 0.0625
    }

    // =================================================================
    // 5. Validation
    // =========================================================================

    fn validate_format() -> bool {
        const fmt = goldenfloat_family::get_format_by_name("GF8");
        return (fmt != null) &&
               (fmt.?.bits == BITS) &&
               (fmt.?.exp_bits == EXP_BITS) &&
               (fmt.?.mant_bits == MANT_BITS);
    }

    // =================================================================
    // 6. Use Cases
    // =========================================================================

    // GF8 is optimal for:
    // - High compression (75% smaller than FP32)
    // - Weight quantization for lightweight models
    // - Activation caching
    // - Intermediate feature maps

    // Memory: 8 bits = 1 byte (4x FP32 in same space)
    const MEMORY_RATIO_VS_FP32 : f32 = 8.0 / 32.0;  // 0.25

    // =================================================================
    // 7. Helper Functions
    // =========================================================================

    fn floor_log2(x: f32) -> i8 {
        if (x <= 0.0) { return -128; }
        let exp : i8 = 0;
        while (x >= 2.0) {
            x = x / 2.0;
            exp = exp + 1;
        }
        while (x < 1.0) {
            x = x * 2.0;
            exp = exp - 1;
        }
        return exp;
    }

    fn extract_mantissa(value: f32, exp: i8, mant_bits: u8) -> u8 {
        const normalized = value / pow(2.0, exp as f32);
        const frac = normalized - 1.0;
        const max_mant = (1 << mant_bits) - 1;
        return (frac * (max_mant as f32 + 1.0)) as u8;
    }

    fn clamp(x: u8, min: u8, max: u8) -> u8 {
        if (x < min) { return min; }
        if (x > max) { return max; }
        return x;
    }

    fn pow(base: f32, exp: f32) -> f32 {
        // Efficient power function for GF8
        // Integer exponent: binary exponentiation
        // Fractional exponent: use logarithm approximation

        if (base <= 0.0 || exp == 0.0) {
            if (exp == 0.0) {
                return 1.0;
            }
            if (base == 0.0 && exp > 0.0) {
                return 0.0;
            }
            return 0.0 / 0.0;  // NaN for negative base with non-integer exp
        }

        // Check if exponent is (approximately) integer
        const is_integer = exp == floor(exp);

        if (is_integer) {
            // Binary exponentiation for integer exponents
            let exp_int = exp as i32;
            let result = 1.0;
            let base_acc = base;
            let e = exp_int;

            if (e < 0) {
                e = -e;
                base_acc = 1.0 / base_acc;
            }

            while (e > 0) {
                if (e % 2 == 1) {
                    result = result * base_acc;
                }
                base_acc = base_acc * base_acc;
                e = e / 2;
            }

            return result;
        }

        // Fractional exponent: x^y = exp(y * ln(x))
        const ln_val = ln_approx(base);
        return exp_approx(exp * ln_val);
    }

    // Natural logarithm approximation
    fn ln_approx(x: f32) -> f32 {
        if (x <= 0.0) {
            return 0.0 / 0.0;  // NaN
        }
        if (x == 1.0) {
            return 0.0;
        }

        // Series: ln(x) = 2 * ((x-1)/(x+1) + 1/3*((x-1)/(x+1))^3 + ...)
        const t = (x - 1.0) / (x + 1.0);
        const t2 = t * t;
        const t3 = t2 * t;
        const t5 = t3 * t2;
        const t7 = t5 * t2;

        return 2.0 * (t + t3 / 3.0 + t5 / 5.0 + t7 / 7.0);
    }

    // Exponential approximation
    fn exp_approx(x: f32) -> f32 {
        if (x == 0.0) {
            return 1.0;
        }

        // Taylor series: e^x = 1 + x + x^2/2! + x^3/3! + ...
        let result = 1.0;
        let term = 1.0;
        let exp_x = x;

        // Scale down for large inputs to maintain accuracy
        if (exp_x > 5.0 || exp_x < -5.0) {
            const k = floor(exp_x / 5.0) as i32;
            exp_x = exp_x - (k as f32) * 5.0;
        }

        for (i in 1..=8) {
            term = term * exp_x / (i as f32);
            result = result + term;
        }

        // Scale back if needed
        if (x > 5.0 || x < -5.0) {
            const k = floor(x / 5.0) as i32;
            if (k > 0) {
                for (i in 0..k) {
                    result = result * exp_approx(5.0);
                }
            } else if (k < 0) {
                for (i in k..0) {
                    result = result / exp_approx(5.0);
                }
            }
        }

        return result;
    }

    // Floor function
    fn floor(x: f32) -> f32 {
        let xi = x as i32;
        if (x >= 0.0 || x == xi as f32) {
            return xi as f32;
        }
        return (xi - 1) as f32;
    }

    // =======================================================================================================
    // TDD-Inside-Spec: Tests and Invariants for GF8
    // =======================================================================================================

    test gf8_decode_zero
