// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/spi.t27
// SPI Master Specification for FPGA
// Mode 0: CPOL=0, CPHA=0 (SCK idle low, sample on rising edge)
// phi^2 + 1/phi^2 = 3 | TRINITY

module SPI_Master;
    // Import base types
    use base::types;

    // ===============================================================
    // 1. SPI Configuration
    // =========================================================================

    // System clock
    const CLK_FREQ : u32 = 50_000_000;    // 50 MHz

    // SPI Mode 0: CPOL=0, CPHA=0
    // CPOL (Clock Polarity): 0 = SCK idle low
    // CPHA (Clock Phase): 0 = Sample on first (rising) edge
    const SPI_CPOL : u8 = 0;
    const SPI_CPHA : u8 = 0;

    // SPI configuration
    const MAX_DATA_WIDTH : u8 = 32;       // Max bits per transfer
    const CS_ASSERT_DELAY : u32 = 100;     // CS to SCK delay (ns)
    const CS_DEASSERT_DELAY : u32 = 100;   // SCK to CS delay (ns)

    // SPI prescaler values (divides system clock)
    const PRESCALER_2 : u8 = 0;
    const PRESCALER_4 : u8 = 1;
    const PRESCALER_8 : u8 = 2;
    const PRESCALER_16 : u8 = 3;
    const PRESCALER_32 : u8 = 4;
    const PRESCALER_64 : u8 = 5;
    const PRESCALER_128 : u8 = 6;
    const PRESCALER_256 : u8 = 7;

    // ===============================================================
    // 2. SPI State Machine
    // =========================================================================

    // SPI states
    const SPI_IDLE : u8 = 0;
    const SPI_CS_ASSERT : u8 = 1;
    const SPI_TRANSFER : u8 = 2;
    const SPI_CS_DEASSERT : u8 = 3;

    // Transfer states
    const TX_BIT : u8 = 0;
    const RX_BIT : u8 = 1;
    const WAIT_EDGE : u8 = 2;

    // ===============================================================
    // 3. SPI Master Unit
    // =========================================================================

    // SPI master state
    struct SPI_Master_Unit {
        state : u8,                // Master state
        tx_state : u8,              // Transfer state
        cs_asserted : bool,          // Chip select state
        busy : bool,                // Transfer in progress

        // Transfer configuration
        prescaler : u8,            // Clock prescaler
        data_width : u8,            // Bits per transfer
        cs_mode : u8,              // CS mode (auto/manual)

        // Data registers
        tx_data : u32,              // Transmit data
        rx_data : u32,              // Receive data
        bit_count : u8,             // Bits transferred
        bit_counter : u32,          // Half-cycle counter

        // CS delay counters
        cs_assert_cnt : u32,        // CS assert delay
        cs_deassert_cnt : u32,      // CS deassert delay
    }

    // Default SPI unit
    var spi : SPI_Master_Unit = SPI_Master_Unit{
        .state = SPI_IDLE,
        .tx_state = TX_BIT,
        .cs_asserted = false,
        .busy = false,

        .prescaler = PRESCALER_16,  // Default: 16x prescaler
        .data_width = 8,           // Default: 8-bit transfers
        .cs_mode = 0,              // Auto CS

        .tx_data = 0,
        .rx_data = 0,
        .bit_count = 0,
        .bit_counter = 0,

        .cs_assert_cnt = 0,
        .cs_deassert_cnt = 0,
    };

    // spi_set_prescaler(psc: u8) -> bool
    // Set SPI clock prescaler
    fn spi_set_prescaler(psc: u8) -> bool {
        if (psc > PRESCALER_256) {
            return false;
        }
        spi.prescaler = psc;
        return true;
    }

    // spi_get_prescaler_div() -> u32
    // Get actual prescaler divider value
    fn spi_get_prescaler_div() -> u32 {
        match spi.prescaler {
            PRESCALER_2 => 2u32,
            PRESCALER_4 => 4u32,
            PRESCALER_8 => 8u32,
            PRESCALER_16 => 16u32,
            PRESCALER_32 => 32u32,
            PRESCALER_64 => 64u32,
            PRESCALER_128 => 128u32,
            PRESCALER_256 => 256u32,
            _ => 16u32,
        }
    }

    // spi_get_sck_freq() -> u32
    // Get SPI SCK frequency
    fn spi_get_sck_freq() -> u32 {
        return CLK_FREQ / spi_get_prescaler_div();
    }

    // spi_set_data_width(width: u8) -> bool
    // Set data width (1-32 bits)
    fn spi_set_data_width(width: u8) -> bool {
        if (width == 0 || width > MAX_DATA_WIDTH) {
            return false;
        }
        spi.data_width = width;
        return true;
    }

    // spi_is_busy() -> bool
    // Check if SPI is busy
    fn spi_is_busy() -> bool {
        return spi.busy;
    }

    // spi_transfer(data: u32) -> bool
    // Start SPI transfer
    fn spi_transfer(data: u32) -> bool {
        if (spi.busy) {
            return false;
        }
        spi.tx_data = data;
        spi.rx_data = 0;
        spi.bit_count = 0;
        spi.bit_counter = 0;
        spi.state = SPI_CS_ASSERT;
        spi.busy = true;
        return true;
    }

    // spi_read_rx() -> u32
    // Read received data (lower bits only)
    fn spi_read_rx() -> u32 {
        return spi.rx_data & ((1u32 << spi.data_width) - 1);
    }

    // spi_get_cs() -> bool
    // Get CS line state
    fn spi_get_cs() -> bool {
        return spi.cs_asserted;
    }

    // spi_get_sck() -> bool
    // Get SCK line state (Mode 0: idle low)
    fn spi_get_sck() -> bool {
        // In Mode 0: SCK is low in idle
        // Alternates during transfer
        match spi.tx_state {
            TX_BIT => false,   // SCK low (setup)
            RX_BIT => true,    // SCK high (sample)
            _ => SPI_CPOL == 0,
        }
    }

    // spi_get_mosi() -> bool
    // Get MOSI line state
    fn spi_get_mosi() -> bool {
        if (!spi.busy || spi.state != SPI_TRANSFER) {
            return false;  // Idle: MOSI low
        }
        return (spi.tx_data >> (spi.data_width - spi.bit_count - 1)) & 1 == 1;
    }

    // spi_tick() -> void
    // Process one system clock cycle
    fn spi_tick() -> void {
        match spi.state {
            SPI_IDLE => {
                // Do nothing, waiting for transfer
            }
            SPI_CS_ASSERT => {
                spi.cs_assert_cnt = spi.cs_assert_cnt + 1;
                if (spi.cs_assert_cnt >= (CS_ASSERT_DELAY * CLK_FREQ / 1_000_000_000)) {
                    spi.cs_assert_cnt = 0;
                    spi.cs_asserted = true;
                    spi.state = SPI_TRANSFER;
                    spi.tx_state = TX_BIT;
                }
            }
            SPI_TRANSFER => {
                spi_transfer_bit();
            }
            SPI_CS_DEASSERT => {
                spi.cs_deassert_cnt = spi.cs_deassert_cnt + 1;
                if (spi.cs_deassert_cnt >= (CS_DEASSERT_DELAY * CLK_FREQ / 1_000_000_000)) {
                    spi.cs_deassert_cnt = 0;
                    spi.cs_asserted = false;
                    spi.state = SPI_IDLE;
                    spi.busy = false;
                }
            }
        }
    }

    // spi_transfer_bit() -> void
    // Transfer single bit
    fn spi_transfer_bit() -> void {
        const prescaler_div = spi_get_prescaler_div();
        spi.bit_counter = spi.bit_counter + 1;

        match spi.tx_state {
            TX_BIT => {
                if (spi.bit_counter >= prescaler_div / 2) {
                    spi.bit_counter = 0;
                    spi.tx_state = RX_BIT;
                }
            }
            RX_BIT => {
                if (spi.bit_counter >= prescaler_div / 2) {
                    // Sample MISO -- in spec-level simulation this is a placeholder;
                    // Verilog emission reads the actual MISO input pin
                    const miso_bit = false;
                    spi.rx_data = (spi.rx_data << 1) | (if miso_bit { 1u32 } else { 0u32 });
                    spi.bit_count = spi.bit_count + 1;
                    spi.bit_counter = 0;

                    if (spi.bit_count >= spi.data_width) {
                        spi.tx_state = WAIT_EDGE;
                    } else {
                        spi.tx_state = TX_BIT;
                    }
                }
            }
            WAIT_EDGE => {
                if (spi.bit_counter >= prescaler_div / 2) {
                    spi.bit_counter = 0;
                    spi.state = SPI_CS_DEASSERT;
                }
            }
        }
    }

    // ===========================================================================================
    // TDD-Inside-Spec: Tests and Invariants for SPI_Master
    // ===========================================================================================

    test spi_mode_0_configuration
        given cpol = SPI_CPOL
        and   cpha = SPI_CPHA
        then cpol == 0 and cpha == 0

    test spi_prescaler_16_default
        given psc = spi.prescaler
        then psc == PRESCALER_16

    test spi_set_prescaler_valid
        given result = spi_set_prescaler(PRESCALER_64)
        then result == true

    test spi_set_prescaler_invalid
        given result = spi_set_prescaler(99)
        then result == false

    test spi_prescaler_div_16
        given psc = PRESCALER_16
        and   div = spi_get_prescaler_div()
        then div == 16

    test spi_sck_freq_at_50MHz
        given freq = spi_get_sck_freq()
        and   div = spi_get_prescaler_div()
        then freq == CLK_FREQ / div

    test spi_set_data_width_8
        given result = spi_set_data_width(8)
        then result == true

    test spi_set_data_width_32
        given result = spi_set_data_width(32)
        then result == true

    test spi_set_data_width_invalid
        given result = spi_set_data_width(0)
        then result == false

    test spi_initially_not_busy
        given busy = spi_is_busy()
        then busy == false

    test spi_transfer_when_ready
        given result = spi_transfer(0xAA)
        then result == true

    test spi_transfer_when_busy
        given spi_transfer(0x55)
        and   result = spi_transfer(0xAA)
        then result == false

    test spi_cs_idle_high
        given cs = spi_get_cs()
        then cs == false

    test spi_sck_idle_low
        given sck = spi_get_sck()
        then sck == false  // Mode 0: idle low

    test spi_max_data_width_32
        given max = MAX_DATA_WIDTH
        then max == 32

    test spi_prescaler_range
        given min_psc = PRESCALER_2
        and   max_psc = PRESCALER_256
        then min_psc == 0 and max_psc == 7

    test spi_cs_delays_defined
        given assert_delay = CS_ASSERT_DELAY
        and   deassert_delay = CS_DEASSERT_DELAY
        then assert_delay == 100 and deassert_delay == 100

    invariant spi_mode_0_constant
        assert SPI_CPOL == 0 and SPI_CPHA == 0

    invariant spi_states_valid
        given state = spi.state
        assert state == SPI_IDLE or state == SPI_CS_ASSERT or state == SPI_TRANSFER or state == SPI_CS_DEASSERT

    invariant spi_tx_states_valid
        given tx_state = spi.tx_state
        assert tx_state == TX_BIT or tx_state == RX_BIT or tx_state == WAIT_EDGE

    invariant spi_prescaler_divides_clock
        given freq = spi_get_sck_freq()
        assert CLK_FREQ % freq == 0

    invariant spi_data_width_bounds
        assert spi.data_width > 0 and spi.data_width <= MAX_DATA_WIDTH

    invariant spi_busy_implies_cs_asserted
        assert spi.busy implies spi.cs_asserted or spi.state == SPI_CS_ASSERT

    invariant spi_busy_only_in_transfer
        assert spi.busy implies spi.state == SPI_CS_ASSERT or spi.state == SPI_TRANSFER or spi.state == SPI_CS_DEASSERT

    invariant spi_sck_alternates
        given old_sck = spi_get_sck()
        when spi.state == SPI_TRANSFER and spi.tx_state == TX_BIT
        and   spi.tx_state = RX_BIT
        and   new_sck = spi_get_sck()
        then old_sck != new_sck

    invariant spi_cs_deasserted_after_transfer
        given spi.data_width = 8
        and   spi.transfer(0xAA)
        and   // Complete transfer simulation
        then spi.state == SPI_CS_DEASSERT or spi.state == SPI_IDLE

    invariant spi_rx_data_masked
        given spi.data_width = 8
        and   spi.tx_data = 0xAA55AA55
        and   rx = spi_read_rx()
        then rx == rx & 0xFF

    invariant spi_bit_count_reset_after_transfer
        given spi.data_width = 8
        and   spi.bit_count = 8
        when spi.state == SPI_CS_DEASSERT and spi.state == SPI_IDLE
        and   spi.busy == false
        then spi.bit_count == 0

    invariant spi_cs_delay_counters_reset
        given spi.state == SPI_IDLE
        then spi.cs_assert_cnt == 0 and spi.cs_deassert_cnt == 0

    bench spi_transfer_latency
        measure: nanoseconds to complete 8-bit transfer
        target: < 2000ns  // 8 bits * 2 * prescaler / 50MHz

    bench spi_sck_max_frequency
        given spi_set_prescaler(PRESCALER_2)
        and   freq = spi_get_sck_freq()
        then freq == 25_000_000  // 50MHz / 2

    bench spi_cs_assertion_time
        measure: nanoseconds for CS to assert
        target: < 150ns  // CS_ASSERT_DELAY + margin

    bench spi_prescaler_change_latency
        measure: nanoseconds to spi_set_prescaler(PRESCALER_32)
        target: < 100ns

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/fifo.t27
// Synchronous and Asynchronous FIFO Stdlib for Trinity T27 FPGA HIR
// Defines FIFO configuration with depth, data width, and flags
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Fifo {

    // === FIFO kind ===

    pub const FifoKind = enum(i8) {
        sync_fifo = 0,
        async_fifo = 1,
    }

    // === FIFO status flags ===

    pub struct FifoFlags {
        empty : bool,
        full : bool,
        almost_empty : bool,
        almost_full : bool,
    }

    // === FIFO configuration ===

    pub struct FifoConfig {
        name : &str,
        kind : i8,
        depth : u32,
        data_width : u32,
        has_almost_empty : bool,
        has_almost_full : bool,
        almost_empty_threshold : u32,
        almost_full_threshold : u32,
        use_bram : bool,
    }

    // === FIFO runtime state (for simulation) ===

    pub const MAX_FIFO_DEPTH : u32 = 65536;

    pub struct FifoState {
        fill_count : u32,
        head_ptr : u32,
        tail_ptr : u32,
        flags : FifoFlags,
    }

    // === Constructor helpers ===

    fn sync_fifo(name: &str, depth: u32, data_width: u32) -> FifoConfig {
        return FifoConfig{
            .name = name,
            .kind = 0,
            .depth = depth,
            .data_width = data_width,
            .has_almost_empty = false,
            .has_almost_full = false,
            .almost_empty_threshold = 0,
            .almost_full_threshold = 0,
            .use_bram = true,
        };
    }

    fn async_fifo(name: &str, depth: u32, data_width: u32) -> FifoConfig {
        return FifoConfig{
            .name = name,
            .kind = 1,
            .depth = depth,
            .data_width = data_width,
            .has_almost_empty = false,
            .has_almost_full = false,
            .almost_empty_threshold = 0,
            .almost_full_threshold = 0,
            .use_bram = true,
        };
    }

    fn with_almost_empty(cfg: FifoConfig, threshold: u32) -> FifoConfig {
        var result = cfg;
        result.has_almost_empty = true;
        result.almost_empty_threshold = threshold;
        return result;
    }

    fn with_almost_full(cfg: FifoConfig, threshold: u32) -> FifoConfig {
        var result = cfg;
        result.has_almost_full = true;
        result.almost_full_threshold = threshold;
        return result;
    }

    fn empty_fifo_state() -> FifoState {
        return FifoState{
            .fill_count = 0,
            .head_ptr = 0,
            .tail_ptr = 0,
            .flags = FifoFlags{
                .empty = true,
                .full = false,
                .almost_empty = false,
                .almost_full = false,
            },
        };
    }

    // === Query functions ===

    fn is_sync(cfg: FifoConfig) -> bool {
        return cfg.kind == 0;
    }

    fn is_async(cfg: FifoConfig) -> bool {
        return cfg.kind == 1;
    }

    fn addr_width(cfg: FifoConfig) -> u32 {
        var d : u32 = cfg.depth;
        var w : u32 = 0;
        while (d > 1) {
            w = w + 1;
            d = d / 2;
        }
        if (w == 0) {
            w = 1;
        }
        return w;
    }

    fn total_storage_bits(cfg: FifoConfig) -> u32 {
        return cfg.depth * cfg.data_width;
    }

    fn bram18_count(cfg: FifoConfig) -> u32 {
        var bits : u32 = cfg.depth * cfg.data_width;
        var count : u32 = bits / 18432;
        if (bits % 18432 > 0) {
            count = count + 1;
        }
        return count;
    }

    fn is_empty(state: FifoState) -> bool {
        return state.flags.empty;
    }

    fn is_full(state: FifoState) -> bool {
        return state.flags.full;
    }

    fn fill_count(state: FifoState) -> u32 {
        return state.fill_count;
    }

    fn has_space(state: FifoState) -> bool {
        return state.flags.full == false;
    }

    fn has_data(state: FifoState) -> bool {
        return state.flags.empty == false;
    }

    // === Push/Pop state updates ===

    fn push(state: FifoState, cfg: FifoConfig) -> FifoState {
        var result = state;
        if (state.flags.full) {
            return result;
        }
        result.tail_ptr = (state.tail_ptr + 1) % cfg.depth;
        result.fill_count = state.fill_count + 1;
        result.flags.empty = false;
        if (result.fill_count == cfg.depth) {
            result.flags.full = true;
        }
        return result;
    }

    fn pop(state: FifoState, cfg: FifoConfig) -> FifoState {
        var result = state;
        if (state.flags.empty) {
            return result;
        }
        result.head_ptr = (state.head_ptr + 1) % cfg.depth;
        result.fill_count = state.fill_count - 1;
        result.flags.full = false;
        if (result.fill_count == 0) {
            result.flags.empty = true;
        }
        return result;
    }

    // === Validation ===

    fn validate_fifo(cfg: FifoConfig) -> u32 {
        var errors : u32 = 0;

        if (cfg.name == "") {
            errors = errors + 1;
        }
        if (cfg.depth == 0 {
            errors = errors + 1;
        }
        if (cfg.data_width == 0 {
            errors = errors + 1;
        }
        if (cfg.has_almost_empty and cfg.almost_empty_threshold >= cfg.depth {
            errors = errors + 1;
        }
        if (cfg.has_almost_full and cfg.almost_full_threshold >= cfg.depth {
            errors = errors + 1;
        }

        return errors;
    }

    // === Tests ===

    test sync_fifo_is_sync
        given f = sync_fifo("tx_fifo", 16, 8)
        then is_sync(f) == true
        and is_async(f) == false

    test async_fifo_is_async
        given f = async_fifo("cross_fifo", 32, 16)
        then is_async(f) == true
        and is_sync(f) == false

    test addr_width_16
        given f = sync_fifo("f", 16, 8)
        then addr_width(f) == 4

    test addr_width_256
        given f = sync_fifo("f", 256, 32)
        then addr_width(f) == 8

    test total_storage_bits
        given f = sync_fifo("f", 16, 32)
        then total_storage_bits(f) == 512

    test bram18_small
        given f = sync_fifo("f", 16, 32)
        then bram18_count(f) == 1

    test empty_state_is_empty
        given s = empty_fifo_state()
        then is_empty(s) == true
        and is_full(s) == false
        and fill_count(s) == 0
        and has_data(s) == false
        and has_space(s) == true

    test push_increments_fill
        given cfg = sync_fifo("f", 4, 8)
        and s = empty_fifo_state()
        and s2 = push(s, cfg)
        then fill_count(s2) == 1
        and is_empty(s2) == false

    test push_to_full
        given cfg = sync_fifo("f", 2, 8)
        and s = empty_fifo_state()
        and s2 = push(s, cfg)
        and s3 = push(s2, cfg)
        then is_full(s3) == true
        and fill_count(s3) == 2

    test push_on_full_noop
        given cfg = sync_fifo("f", 2, 8)
        and s = empty_fifo_state()
        and s2 = push(s, cfg)
        and s3 = push(s2, cfg)
        and s4 = push(s3, cfg)
        then fill_count(s4) == 2

    test pop_decrements_fill
        given cfg = sync_fifo("f", 4, 8)
        and s = empty_fifo_state()
        and s2 = push(s, cfg)
        and s3 = pop(s2, cfg)
        then fill_count(s3) == 0
        and is_empty(s3) == true

    test pop_on_empty_noop
        given cfg = sync_fifo("f", 4, 8)
        and s = empty_fifo_state()
        and s2 = pop(s, cfg)
        then fill_count(s2) == 0

    test push_pop_roundtrip
        given cfg = sync_fifo("f", 4, 8)
        and s = empty_fifo_state()
        and s2 = push(s, cfg)
        and s3 = push(s2, cfg)
        and s4 = pop(s3, cfg)
        then fill_count(s4) == 1
        and has_data(s4) == true
        and has_space(s4) == true

    test with_almost_empty
        given f = sync_fifo("f", 16, 8)
        and f2 = with_almost_empty(f, 2)
        then f2.has_almost_empty == true
        and f2.almost_empty_threshold == 2

    test with_almost_full
        given f = sync_fifo("f", 16, 8)
        and f2 = with_almost_full(f, 14)
        then f2.has_almost_full == true
        and f2.almost_full_threshold == 14

    test validate_ok
        given f = sync_fifo("f", 16, 8)
        then validate_fifo(f) == 0

    test validate_empty_name
        given f = sync_fifo("", 16, 8)
        then validate_fifo(f) > 0

    test validate_zero_depth
        given f = FifoConfig{.name = "x", .kind = 0, .depth = 0, .data_width = 8, .has_almost_empty = false, .has_almost_full = false, .almost_empty_threshold = 0, .almost_full_threshold = 0, .use_bram = true}
        then validate_fifo(f) > 0

    // === Invariants ===

    invariant fill_count_non_negative
        given s = empty_fifo_state()
        assert fill_count(s) >= 0

    invariant fill_count_le_depth
        given cfg = sync_fifo("inv", 16, 8)
        and s = push(empty_fifo_state(), cfg)
        assert fill_count(s) <= cfg.depth

    invariant empty_xor_full
        given s = empty_fifo_state()
        assert (is_empty(s) and is_full(s)) == false

    invariant has_space_iff_not_full
        given s = empty_fifo_state()
        assert has_space(s) == (is_full(s) == false)

    invariant has_data_iff_not_empty
        given s = empty_fifo_state()
        assert has_data(s) == (is_empty(s) == false)

    invariant bram18_positive
        given f = sync_fifo("inv", 16, 8)
        assert bram18_count(f) > 0

    // === Benchmarks ===

    bench push_latency
        measure: nanoseconds to push(empty_fifo_state(), sync_fifo("b", 16, 8))
        target: < 100ns

    bench pop_latency
        measure: nanoseconds to pop(push(empty_fifo_state(), sync_fifo("b", 16, 8)), sync_fifo("b", 16, 8))
        target: < 100ns
}

