// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_pattern_matching.t27
// Ternary Pattern Matching Operations Specification
// Ring 082 - Pattern matching algorithms for ternary sequences
// 01 + 1/23 = 3 | TRINITY

module TernaryPatternMatching {
    use base::types;

    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // match_exact: Find first exact match of pattern in text, return index or -1
    fn match_exact(text: []i32, pattern: []i32) i64 {
        if (pattern.len == 0 or pattern.len > text.len) { return -1; }
        var i : usize = 0;
        while (i <= text.len - pattern.len) {
            var j : usize = 0;
            var matched : bool = true;
            while (j < pattern.len and matched) {
                if (text[i + j] != pattern[j]) {
                    matched = false;
                }
                j = j + 1;
            }
            if (matched) {
                return i as i64;
            }
            i = i + 1;
        }
        return -1;
    }

    // match_count: Count all non-overlapping occurrences of pattern
    fn match_count(text: []i32, pattern: []i32) usize {
        if (pattern.len == 0 or pattern.len > text.len) { return 0; }
        var count : usize = 0;
        var i : usize = 0;
        while (i <= text.len - pattern.len) {
            var j : usize = 0;
            var matched : bool = true;
            while (j < pattern.len and matched) {
                if (text[i + j] != pattern[j]) {
                    matched = false;
                }
                j = j + 1;
            }
            if (matched) {
                count = count + 1;
                i = i + pattern.len;
            } else {
                i = i + 1;
            }
        }
        return count;
    }

    // match_wildcard: Match with wildcard (TRIT_ZERO matches any value)
    fn match_wildcard(text: []i32, pattern: []i32) i64 {
        if (pattern.len == 0 or pattern.len > text.len) { return -1; }
        var i : usize = 0;
        while (i <= text.len - pattern.len) {
            var j : usize = 0;
            var matched : bool = true;
            while (j < pattern.len and matched) {
                if (pattern[j] != TRIT_ZERO and text[i + j] != pattern[j]) {
                    matched = false;
                }
                j = j + 1;
            }
            if (matched) {
                return i as i64;
            }
            i = i + 1;
        }
        return -1;
    }

    // hamming_distance: Count mismatched positions between equal-length sequences
    fn hamming_distance(a: []i32, b: []i32) usize {
        var dist : usize = 0;
        var len : usize = a.len;
        if (b.len < len) { len = b.len; }
        var i : usize = 0;
        while (i < len) {
            if (a[i] != b[i]) {
                dist = dist + 1;
            }
            i = i + 1;
        }
        return dist;
    }

    // longest_common_prefix: Find length of shared prefix
    fn longest_common_prefix(a: []i32, b: []i32) usize {
        var len : usize = a.len;
        if (b.len < len) { len = b.len; }
        var i : usize = 0;
        while (i < len and a[i] == b[i]) {
            i = i + 1;
        }
        return i;
    }

    // test: exact match finds pattern
    test match_exact_found {
        var text = [6]i32{ -1, 0, 1, 0, -1, 1 };
        var pat = [2]i32{ 1, 0 };
        try eq(match_exact(text[0..], pat[0..]), 2);
    }

    // test: exact match returns -1 when not found
    test match_exact_miss {
        var text = [4]i32{ -1, -1, 0, 0 };
        var pat = [2]i32{ 1, 1 };
        try eq(match_exact(text[0..], pat[0..]), -1);
    }

    // test: match_count counts non-overlapping
    test match_count_noverlap {
        var text = [6]i32{ 1, 0, 1, 0, 1, 0 };
        var pat = [2]i32{ 1, 0 };
        try eq(match_count(text[0..], pat[0..]), 3);
    }

    // test: wildcard match
    test wildcard_match {
        var text = [4]i32{ -1, 1, 0, -1 };
        var pat = [2]i32{ -1, TRIT_ZERO };
        try eq(match_wildcard(text[0..], pat[0..]), 0);
    }

    // test: hamming distance
    test hamming {
        var a = [4]i32{ -1, 0, 1, 1 };
        var b = [4]i32{ -1, 1, 1, -1 };
        try eq(hamming_distance(a[0..], b[0..]), 2);
    }

    // test: longest common prefix
    test lcp {
        var a = [4]i32{ -1, 0, 1, 1 };
        var b = [4]i32{ -1, 0, -1, 0 };
        try eq(longest_common_prefix(a[0..], b[0..]), 2);
    }

    // invariant: hamming distance is symmetric
    invariant hamming_symmetric {
        var a = [3]i32{ -1, 0, 1 };
        var b = [3]i32{ 1, 0, -1 };
        hamming_distance(a[0..], b[0..]) == hamming_distance(b[0..], a[0..]);
    }

    // invariant: lcp <= min(len(a), len(b))
    invariant lcp_bound {
        var a = [3]i32{ -1, 0, 1 };
        var b = [5]i32{ -1, 0, 1, -1, 0 };
        longest_common_prefix(a[0..], b[0..]) <= a.len;
    }

    // bench: match_exact 81-char text, 9-char pattern
    bench match_exact_81 {
        var text : [81]i32;
        var pat : [9]i32;
        var i : usize = 0;
        while (i < 81) { text[i] = (i as i32) % 3 - 1; i = i + 1; }
        var j : usize = 0;
        while (j < 9) { pat[j] = (j as i32) % 3 - 1; j = j + 1; }
        match_exact(text[0..], pat[0..]);
    }
}

// SPDX-License-Identifier: Apache-2.0
module Pipeline {
    use compiler::lexer;
    use compiler::parser;
    use compiler::typechecker;
    use compiler::optimizer;
    use compiler::stdlib;
    use compiler::diagnostics;
    use compiler::linker;

    enum PipelineStage {
        Lex = 0,
        Parse = 1,
        TypeCheck = 2,
        Optimize = 3,
        Codegen = 4,
        Link = 5,
    }

    struct PipelineConfig {
        target_backend: str;
        opt_level: u32;
        emit_debug: bool;
        emit_comments: bool;
        check_only: bool;
    }

    struct PipelineResult {
        success: bool;
        stage_reached: u32;
        lex_tokens: u32;
        parse_nodes: u32;
        type_errors: u32;
        opt_folds: u32;
        opt_dead: u32;
        opt_copies: u32;
        opt_strengths: u32;
        gen_lines: u32;
        error_msg: str;
    }

    fn default_pipeline_config() -> PipelineConfig {
        return PipelineConfig{
            target_backend = "zig",
            opt_level = 1,
            emit_debug = false,
            emit_comments = false,
            check_only = false,
        };
    }

    fn pipeline_result_ok(stage: u32) -> PipelineResult {
        return PipelineResult{
            success = true,
            stage_reached = stage,
            lex_tokens = 0,
            parse_nodes = 0,
            type_errors = 0,
            opt_folds = 0,
            opt_dead = 0,
            opt_copies = 0,
            opt_strengths = 0,
            gen_lines = 0,
            error_msg = "",
        };
    }

    fn pipeline_result_fail(stage: u32, msg: str) -> PipelineResult {
        return PipelineResult{
            success = false,
            stage_reached = stage,
            lex_tokens = 0,
            parse_nodes = 0,
            type_errors = 0,
            opt_folds = 0,
            opt_dead = 0,
            opt_copies = 0,
            opt_strengths = 0,
            gen_lines = 0,
            error_msg = msg,
        };
    }

    fn stage_name(stage: u32) -> str {
        if (stage == 0) { return "lex"; }
        if (stage == 1) { return "parse"; }
        if (stage == 2) { return "typecheck"; }
        if (stage == 3) { return "optimize"; }
        if (stage == 4) { return "codegen"; }
        if (stage == 5) { return "link"; }
        return "unknown";
    }

    fn is_full_pipeline(r: PipelineResult) -> bool {
        return r.success and r.stage_reached >= 4;
    }

    fn total_optimizations(r: PipelineResult) -> u32 {
        return r.opt_folds + r.opt_dead + r.opt_copies + r.opt_strengths;
    }

    test default_config_backend
        given c = default_pipeline_config()
        then c.target_backend == "zig"

    test default_config_opt_level
        given c = default_pipeline_config()
        then c.opt_level == 1

    test pipeline_ok_success
        given r = pipeline_result_ok(4)
        then r.success == true

    test pipeline_ok_stage
        given r = pipeline_result_ok(4)
        then r.stage_reached == 4

    test pipeline_fail_not_success
        given r = pipeline_result_fail(1, "bad token")
        then r.success == false

    test pipeline_fail_stage
        given r = pipeline_result_fail(1, "bad token")
        then r.stage_reached == 1

    test stage_name_lex
        given n = stage_name(0)
        then n == "lex"

    test stage_name_codegen
        given n = stage_name(4)
        then n == "codegen"

    test stage_name_unknown
        given n = stage_name(99)
        then n == "unknown"

    test is_full_pipeline_true
        given r = pipeline_result_ok(5)
        then is_full_pipeline(r) == true

    test is_full_pipeline_false
        given r = pipeline_result_ok(2)
        then is_full_pipeline(r) == false

    test total_optimizations_zero
        given r = pipeline_result_ok(4)
        then total_optimizations(r) == 0

    test total_optimizations_sum
        var r = pipeline_result_ok(4)
        r.opt_folds = 3
        r.opt_dead = 1
        r.opt_copies = 2
        r.opt_strengths = 4
        then total_optimizations(r) == 10

    invariant stage_names_complete
        assert stage_name(0) == "lex"
        assert stage_name(1) == "parse"
        assert stage_name(2) == "typecheck"
        assert stage_name(3) == "optimize"
        assert stage_name(4) == "codegen"
        assert stage_name(5) == "link"

    invariant fail_never_full_pipeline
        given r = pipeline_result_fail(5, "error")
        assert is_full_pipeline(r) == false
}

