// Bandwidth Allocator - fair bandwidth distribution and QoS
// Intelligent bandwidth management for network flows

module BandwidthAllocator {
    use base::types;

    const MAX_FLOWS: u32 = 8;
    const TOTAL_BANDWIDTH: u32 = 1000; // Units per tick
    const MIN_BANDWIDTH: u32 = 10;
    const MAX_BANDWIDTH: u32 = 500;
    // Priority levels used by the flow-requirement tests (were referenced but
    // never declared -- the generated code could not compile in any backend).
    const PRIORITY_LOW: u32 = 1;
    const PRIORITY_MEDIUM: u32 = 2;
    const PRIORITY_HIGH: u32 = 3;

    // Flow requirements [flow_id][priority][min_bw][current_bw]
    fn create_flow_requirement(flow_id: u32, priority: u32, min_bw: u32, current_bw: u32) -> u32 {
        return (((flow_id & 0xFF) << 24) |
                ((priority & 0x3) << 22) |
                ((min_bw & 0x3FF) << 12) |
                (current_bw & 0xFFF));
    }

    fn get_flow_id(req: u32) -> u32 {
        return ((req >> 24) & 0xFF);
    }

    fn get_flow_priority(req: u32) -> u32 {
        return ((req >> 22) & 0x3);
    }

    fn get_min_bandwidth(req: u32) -> u32 {
        return ((req >> 12) & 0x3FF);
    }

    fn get_current_bandwidth(req: u32) -> u32 {
        return (req & 0xFFF);
    }

    // Allocation state [allocated_bw][pending_requests][fair_share][last_update]
    fn create_allocation_state(allocated: u32, pending: u32, fair_share: u32, last_update: u32) -> u32 {
        return (((allocated & 0x7FF) << 21) |
                ((pending & 0xFF) << 13) |
                ((fair_share & 0x1FF) << 4) |
                (last_update & 0xF));
    }

    fn get_allocated_bw(state: u32) -> u32 {
        return ((state >> 21) & 0x7FF);
    }

    fn get_pending_requests(state: u32) -> u32 {
        return ((state >> 13) & 0xFF);
    }

    fn get_fair_share(state: u32) -> u32 {
        return ((state >> 4) & 0x1FF);
    }

    fn get_last_update(state: u32) -> u32 {
        return (state & 0xF);
    }

    // 8-flow storage. Eight 32-bit flow requirements need 256 bits: the old
    // u64 container packed them at 8-bit strides, so every 32-bit read
    // overlapped its neighbors and returned garbage. A real array holds them.
    fn create_flow_array(f0: u32, f1: u32, f2: u32, f3: u32, f4: u32, f5: u32, f6: u32, f7: u32) -> [u32; 8] {
        return [f0, f1, f2, f3, f4, f5, f6, f7];
    }

    fn get_flow_req(array: [u32; 8], index: u32) -> u32 {
        if (index < 8) {
            return array[index];
        }
        return 0;
    }

    // Calculate fair share bandwidth
    fn calculate_fair_share(total_bw: u32, flow_count: u32) -> u32 {
        if (flow_count == 0) {
            return 0;
        }
        return (total_bw / flow_count);
    }

    // Allocate bandwidth to flow (with priority consideration)
    fn allocate_bandwidth(state: u32, flow_req: u32, available_bw: u32) -> u32 {
        let priority = get_flow_priority(flow_req);
        let min_bw = get_min_bandwidth(flow_req);
        let allocated = get_allocated_bw(state);

        // Branch on the declared priority constants (HIGH=3, MEDIUM=2, LOW=1).
        // The old branches keyed on 0/1, which no constant produces -- every
        // caller using PRIORITY_HIGH fell into the low-priority arm.
        let allocation = 0;

        if (priority == PRIORITY_HIGH) {
            // High priority: allocate up to max bandwidth
            allocation = min_bw + ((available_bw * 7) / 10);
        } else if (priority == PRIORITY_MEDIUM) {
            // Medium priority: allocate based on fair share
            allocation = calculate_fair_share(available_bw, 2);
        } else {
            // Low priority: allocate minimum bandwidth
            allocation = min_bw;
        }

        // Ensure allocation doesn't exceed available or max limits
        if (allocation > available_bw) { allocation = available_bw; }
        if (allocation > MAX_BANDWIDTH) { allocation = MAX_BANDWIDTH; }
        if (allocation < min_bw) { allocation = min_bw; }

        let new_allocated = allocated + allocation;
        let pending = get_pending_requests(state);
        let fair_share = get_fair_share(state);
        let update = get_last_update(state);

        return create_allocation_state(new_allocated, pending, fair_share, update);
    }

    // Check if flow needs more bandwidth
    fn needs_more_bandwidth(flow_req: u32) -> bool {
        let current = get_current_bandwidth(flow_req);
        let min_bw = get_min_bandwidth(flow_req);
        return (current < min_bw);
    }

    // Update flow bandwidth allocation
    fn update_flow_bandwidth(flow_req: u32, new_bw: u32) -> u32 {
        let flow_id = get_flow_id(flow_req);
        let priority = get_flow_priority(flow_req);
        let min_bw = get_min_bandwidth(flow_req);

        if (new_bw < min_bw) { new_bw = min_bw; }
        if (new_bw > MAX_BANDWIDTH) { new_bw = MAX_BANDWIDTH; }

        return create_flow_requirement(flow_id, priority, min_bw, new_bw);
    }

    // Count active flows (flows with allocated bandwidth)
    fn count_active_flows(flow_array: [u32; 8]) -> u32 {
        let count = 0;

        if (get_current_bandwidth(get_flow_req(flow_array, 0)) > 0) { count = count + 1; }
        if (get_current_bandwidth(get_flow_req(flow_array, 1)) > 0) { count = count + 1; }
        if (get_current_bandwidth(get_flow_req(flow_array, 2)) > 0) { count = count + 1; }
        if (get_current_bandwidth(get_flow_req(flow_array, 3)) > 0) { count = count + 1; }
        if (get_current_bandwidth(get_flow_req(flow_array, 4)) > 0) { count = count + 1; }
        if (get_current_bandwidth(get_flow_req(flow_array, 5)) > 0) { count = count + 1; }
        if (get_current_bandwidth(get_flow_req(flow_array, 6)) > 0) { count = count + 1; }
        if (get_current_bandwidth(get_flow_req(flow_array, 7)) > 0) { count = count + 1; }

        return count;
    }

    // Find underutilized bandwidth (available bandwidth that can be reclaimed)
    fn find_reclaimable_bandwidth(state: u32, flow_array: [u32; 8]) -> u32 {
        let allocated = get_allocated_bw(state);
        let total_used = 0;

        if (get_current_bandwidth(get_flow_req(flow_array, 0)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 0));
        }
        if (get_current_bandwidth(get_flow_req(flow_array, 1)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 1));
        }
        if (get_current_bandwidth(get_flow_req(flow_array, 2)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 2));
        }
        if (get_current_bandwidth(get_flow_req(flow_array, 3)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 3));
        }
        if (get_current_bandwidth(get_flow_req(flow_array, 4)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 4));
        }
        if (get_current_bandwidth(get_flow_req(flow_array, 5)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 5));
        }
        if (get_current_bandwidth(get_flow_req(flow_array, 6)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 6));
        }
        if (get_current_bandwidth(get_flow_req(flow_array, 7)) > 0) {
            total_used = total_used + get_current_bandwidth(get_flow_req(flow_array, 7));
        }

        if (allocated > total_used) {
            return (allocated - total_used);
        }
        return 0;
    }

    // Priority-based bandwidth allocation
    fn prioritize_bandwidth(flow_array: [u32; 8], available_bw: u32) -> [u32; 8] {
        // Allocate to high priority flows first
        let remaining_bw = available_bw;

        // This is a simplified allocation - in reality would be more sophisticated
        let f0 = get_flow_req(flow_array, 0);
        let f1 = get_flow_req(flow_array, 1);
        let f2 = get_flow_req(flow_array, 2);
        let f3 = get_flow_req(flow_array, 3);
        let f4 = get_flow_req(flow_array, 4);
        let f5 = get_flow_req(flow_array, 5);
        let f6 = get_flow_req(flow_array, 6);
        let f7 = get_flow_req(flow_array, 7);

        return create_flow_array(
            update_flow_bandwidth(f0, calculate_fair_share(remaining_bw, 8)),
            update_flow_bandwidth(f1, calculate_fair_share(remaining_bw, 8)),
            update_flow_bandwidth(f2, calculate_fair_share(remaining_bw, 8)),
            update_flow_bandwidth(f3, calculate_fair_share(remaining_bw, 8)),
            update_flow_bandwidth(f4, calculate_fair_share(remaining_bw, 8)),
            update_flow_bandwidth(f5, calculate_fair_share(remaining_bw, 8)),
            update_flow_bandwidth(f6, calculate_fair_share(remaining_bw, 8)),
            update_flow_bandwidth(f7, calculate_fair_share(remaining_bw, 8))
        );
    }

    // ---- Tests ----

    test create_flow_requirement_basic {
        flow = create_flow_requirement(5, PRIORITY_HIGH, 50, 100);
        assert(get_flow_id(flow) == 5, "flow ID");
        assert(get_flow_priority(flow) == PRIORITY_HIGH, "high priority");
        assert(get_min_bandwidth(flow) == 50, "min bandwidth");
        assert(get_current_bandwidth(flow) == 100, "current bandwidth");
    }

    test create_allocation_state_basic {
        state = create_allocation_state(500, 3, 125, 10);
        assert(get_allocated_bw(state) == 500, "allocated bandwidth");
        assert(get_pending_requests(state) == 3, "pending requests");
        assert(get_fair_share(state) == 125, "fair share");
        assert(get_last_update(state) == 10, "last update");
    }

    test calculate_fair_share_normal {
        let share = calculate_fair_share(1000, 8);
        assert(share == 125, "fair share for 8 flows");
    }

    test calculate_fair_share_zero_flows {
        assert(calculate_fair_share(1000, 0) == 0, "no flows = no share");
    }

    test allocate_bandwidth_high_priority {
        state = create_allocation_state(200, 1, 100, 0);
        flow = create_flow_requirement(5, PRIORITY_HIGH, 50, 100);
        new_state = allocate_bandwidth(state, flow, 300);
        assert(get_allocated_bw(new_state) >= 400, "high priority allocation");
    }

    test allocate_bandwidth_medium_priority {
        state = create_allocation_state(200, 1, 100, 0);
        flow = create_flow_requirement(5, PRIORITY_MEDIUM, 50, 100);
        new_state = allocate_bandwidth(state, flow, 200);
        // Medium priority gets fair share
        assert(get_allocated_bw(new_state) >= 200, "medium priority allocation");
    }

    test allocate_bandwidth_low_priority {
        state = create_allocation_state(200, 1, 100, 0);
        flow = create_flow_requirement(5, PRIORITY_LOW, 50, 100);
        new_state = allocate_bandwidth(state, flow, 200);
        // Low priority gets minimum
