        new_flow = update_flow_bandwidth(flow, 30);
        assert(get_current_bandwidth(new_flow) == 50, "minimum bandwidth respected");
    }

    test update_flow_bandwidth_respects_max {
        flow = create_flow_requirement(5, PRIORITY_HIGH, 50, 100);
        new_flow = update_flow_bandwidth(flow, 600);
        assert(get_current_bandwidth(new_flow) == MAX_BANDWIDTH, "maximum bandwidth respected");
    }

    test count_active_flows_full {
        flow_array = create_flow_array(
            create_flow_requirement(1, PRIORITY_HIGH, 50, 100),
            create_flow_requirement(2, PRIORITY_MEDIUM, 40, 80),
            create_flow_requirement(3, PRIORITY_LOW, 30, 60),
            create_flow_requirement(4, PRIORITY_HIGH, 70, 120),
            create_flow_requirement(5, PRIORITY_MEDIUM, 35, 70),
            create_flow_requirement(6, PRIORITY_LOW, 25, 50),
            create_flow_requirement(7, PRIORITY_HIGH, 60, 110),
            create_flow_requirement(8, PRIORITY_LOW, 20, 40)
        );
        assert(count_active_flows(flow_array) == 8, "8 active flows");
    }

    test count_active_flows_partial {
        flow_array = create_flow_array(
            create_flow_requirement(1, PRIORITY_HIGH, 50, 100),
            create_flow_requirement(2, PRIORITY_MEDIUM, 40, 0),   // Inactive
            create_flow_requirement(3, PRIORITY_LOW, 30, 60),
            create_flow_requirement(4, PRIORITY_HIGH, 70, 0),   // Inactive
            0, 0, 0, 0
        );
        assert(count_active_flows(flow_array) == 2, "2 active flows");
    }

    test find_reclaimable_bandwidth {
        state = create_allocation_state(500, 1, 100, 0);
        flow_array = create_flow_array(
            create_flow_requirement(1, PRIORITY_HIGH, 50, 100),
            create_flow_requirement(2, PRIORITY_MEDIUM, 40, 80),
            create_flow_requirement(3, PRIORITY_LOW, 30, 60),
            create_flow_requirement(4, PRIORITY_HIGH, 70, 120),
            0, 0, 0, 0
        );
        let reclaimable = find_reclaimable_bandwidth(state, flow_array);
        let total_used = 100 + 80 + 60 + 120;
        assert(reclaimable == (500 - total_used), "reclaimable bandwidth calculated");
    }

    test prioritize_bandwidth_distributes {
        flow_array = create_flow_array(
            create_flow_requirement(1, PRIORITY_HIGH, 50, 100),
            create_flow_requirement(2, PRIORITY_MEDIUM, 40, 80),
            create_flow_requirement(3, PRIORITY_LOW, 30, 60),
            create_flow_requirement(4, PRIORITY_HIGH, 70, 120),
            0, 0, 0, 0
        );
        let new_array = prioritize_bandwidth(flow_array, 800);
        // Each flow should get fair share of 800/8 = 100
        assert(get_current_bandwidth(get_flow_req(new_array, 0)) == 100, "flow 0 bandwidth");
        assert(get_current_bandwidth(get_flow_req(new_array, 1)) == 100, "flow 1 bandwidth");
    }
}

// Anomaly Detector - behavioral anomaly detection
// Enables detection of unusual network behavior

module anomaly_detector {
    use base::types;

    const MAX_METRICS: u32 = 16;
    const BASELINE_WINDOW: u32 = 8;
    const ANOMALY_THRESHOLD: u32 = 30;
    const SEVERITY_HIGH: u32 = 80;
    const SEVERITY_MEDIUM: u32 = 50;

    // Metric reading [metric_id][value][timestamp][confidence]
    fn create_metric_reading(metric_id: u32, value: u32, timestamp: u32, confidence: u32) -> u32 {
        return (((metric_id & 0xFF) << 24) |
                ((value & 0xFF) << 16) |
                ((timestamp & 0xFF) << 8) |
                (confidence & 0xFF));
    }

    fn get_metric_id(reading: u32) -> u32 {
        return ((reading >> 24) & 0xFF);
    }

    fn get_metric_value(reading: u32) -> u32 {
        return ((reading >> 16) & 0xFF);
    }

    fn get_timestamp(reading: u32) -> u32 {
        return ((reading >> 8) & 0xFF);
    }

    fn get_confidence(reading: u32) -> u32 {
        return (reading & 0xFF);
    }

    // Anomaly report [metric_id][severity][type][confidence]
    fn create_anomaly_report(metric_id: u32, severity: u32, anomaly_type: u32, confidence: u32) -> u32 {
        return (((metric_id & 0xFF) << 24) |
                ((severity & 0xFF) << 16) |
                ((anomaly_type & 0x3) << 14) |
                (confidence & 0x3FFF));
    }

    fn get_anomaly_metric_id(report: u32) -> u32 {
        return ((report >> 24) & 0xFF);
    }

    fn get_severity(report: u32) -> u32 {
        return ((report >> 16) & 0xFF);
    }

    fn get_anomaly_type(report: u32) -> u32 {
        return ((report >> 14) & 0x3);
    }

    fn get_anomaly_confidence(report: u32) -> u32 {
        return (report & 0x3FFF);
    }

    // Anomaly types
    const TYPE_SPIKE: u32 = 0;
    const TYPE_DROP: u32 = 1;
    const TYPE_PATTERN: u32 = 2;
    const TYPE_TREND: u32 = 3;

    // Calculate baseline from historical data
    fn calculate_baseline(history: [u32; MAX_METRICS], count: u32) -> u32 {
        let sum: u32 = 0;
        let valid_count: u32 = 0;
        let i: u32 = 0;

        while (i < count) {
            let value: u32 = get_metric_value(history[i]);
            sum = sum + value;
            valid_count = valid_count + 1;
            i = i + 1;
        }

        if (valid_count > 0) {
            return sum / valid_count;
        } else {
            return 0;
        }
    }

    // Calculate variance
    fn calculate_variance(history: [u32; MAX_METRICS], count: u32, baseline: u32) -> u32 {
        let sum_diff: u32 = 0;
        let i: u32 = 0;

        while (i < count) {
            let value: u32 = get_metric_value(history[i]);
            let diff: u32 = 0;

            if (value > baseline) {
                diff = value - baseline;
            } else {
                diff = baseline - value;
            }

            sum_diff = sum_diff + diff;
            i = i + 1;
        }

        if (count > 0) {
            return sum_diff / count;
        } else {
            return 0;
        }
    }

    // Detect spike anomaly
    fn detect_spike(current: u32, baseline: u32, variance: u32) -> u32 {
        if (current > baseline) {
            let increase: u32 = current - baseline;

            // Check if increase is significantly above variance
            if (variance > 0) {
                let threshold: u32 = variance * 3;
                if (increase > threshold) {
                    return 1;
                }
            } else if (increase > ANOMALY_THRESHOLD) {
                return 1;
            }
        }

        return 0;
    }

    // Detect drop anomaly
    fn detect_drop(current: u32, baseline: u32, variance: u32) -> u32 {
        if (current < baseline) {
            let decrease: u32 = baseline - current;

            // Check if decrease is significantly above variance
            if (variance > 0) {
                let threshold: u32 = variance * 3;
                if (decrease > threshold) {
                    return 1;
                }
            } else if (decrease > ANOMALY_THRESHOLD) {
                return 1;
            }
        }

        return 0;
    }

    // Detect pattern anomaly
    fn detect_pattern(history: [u32; MAX_METRICS], count: u32) -> u32 {
        if (count < 4) {
            return 0;
        }

        // Check for repeating unusual pattern
        let pattern_count: u32 = 0;
        let i: u32 = 0;

        while (i < count - 2) {
            let val1: u32 = get_metric_value(history[i]);
            let val2: u32 = get_metric_value(history[i + 1]);
            let val3: u32 = get_metric_value(history[i + 2]);

            // Check if pattern repeats (high-low-high or low-high-low)
            if ((val1 > val2 && val2 < val3) || (val1 < val2 && val2 > val3)) {
                pattern_count = pattern_count + 1;
            }

            i = i + 1;
        }

        if (pattern_count >= 2) {
            return 1;
        } else {
            return 0;
        }
    }

    // Detect trend anomaly
    fn detect_trend(history: [u32; MAX_METRICS], count: u32) -> u32 {
        if (count < 4) {
            return 0;
        }

        // Calculate trend direction
        let increases: u32 = 0;
        let decreases: u32 = 0;
        let i: u32 = 0;

        while (i < count - 1) {
            let current: u32 = get_metric_value(history[i]);
            let next: u32 = get_metric_value(history[i + 1]);

            if (next > current) {
                increases = increases + 1;
            } else if (next < current) {
                decreases = decreases + 1;
            }

            i = i + 1;
        }

        // Check if trend is too strong (>80% in one direction)
        let total: u32 = increases + decreases;
        if (total > 0) {
            let increase_ratio: u32 = (increases * 100) / total;
            let decrease_ratio: u32 = (decreases * 100) / total;

            if (increase_ratio > 80 || decrease_ratio > 80) {
                return 1;
            }
        }

        return 0;
    }

    // Calculate anomaly severity
    fn calculate_severity(current: u32, baseline: u32) -> u32 {
        let diff: u32 = 0;
        if (current > baseline) {
            diff = current - baseline;
        } else {
            diff = baseline - current;
        }

        if (diff > SEVERITY_HIGH) {
            return 90; // high severity
        } else if (diff > SEVERITY_MEDIUM) {
            return 60; // medium severity
        } else {
            return 30; // low severity
        }
    }

    // Detect anomaly in metric
    fn detect_anomaly(history: [u32; MAX_METRICS], count: u32, current_reading: u32) -> u32 {
        if (count < BASELINE_WINDOW) {
            return 0; // not enough data
        }

        let baseline: u32 = calculate_baseline(history, count);
        let variance: u32 = calculate_variance(history, count, baseline);
        let current: u32 = get_metric_value(current_reading);
        let metric_id: u32 = get_metric_id(current_reading);

        // Check different anomaly types
        let anomaly_type: u32 = 0;
        let severity: u32 = 0;

        if (detect_spike(current, baseline, variance) == 1) {
            anomaly_type = TYPE_SPIKE;
            severity = calculate_severity(current, baseline);
        } else if (detect_drop(current, baseline, variance) == 1) {
            anomaly_type = TYPE_DROP;
            severity = calculate_severity(current, baseline);
        } else if (detect_pattern(history, count) == 1) {
            anomaly_type = TYPE_PATTERN;
            severity = 50;
        } else if (detect_trend(history, count) == 1) {
            anomaly_type = TYPE_TREND;
            severity = 40;
        }

        if (anomaly_type != 0) {
            return create_anomaly_report(metric_id, severity, anomaly_type, 80);
        } else {
            return 0;
        }
    }

    // Check if anomaly is critical
    fn is_critical_anomaly(report: u32) -> u32 {
        let severity: u32 = get_severity(report);

        if (severity >= SEVERITY_HIGH) {
            return 1;
        } else {
            return 0;
        }
    }

    // Get anomaly description
    fn get_anomaly_description(report: u32) -> u32 {
        let anomaly_type: u32 = get_anomaly_type(report);

        if (anomaly_type == TYPE_SPIKE) {
            return 1; // spike detected
        } else if (anomaly_type == TYPE_DROP) {
            return 2; // drop detected
        } else if (anomaly_type == TYPE_PATTERN) {
            return 3; // unusual pattern
        } else if (anomaly_type == TYPE_TREND) {
            return 4; // strong trend
        } else {
            return 0; // unknown
        }
    }

    // Multiple metric correlation
    fn correlate_metrics(metric1_id: u32, metric2_id: u32, 
                        history1: [u32; MAX_METRICS], history2: [u32; MAX_METRICS], 
                        count: u32) -> u32 {
        if (count < 4) {
            return 0;
        }

        // Simple correlation: do both metrics move in same direction?
        let same_direction: u32 = 0;
        let i: u32 = 0;

        while (i < count - 1) {
            let val1_current: u32 = get_metric_value(history1[i]);
            let val1_next: u32 = get_metric_value(history1[i + 1]);
            let val2_current: u32 = get_metric_value(history2[i]);
            let val2_next: u32 = get_metric_value(history2[i + 1]);

            let direction1: u32 = 0;
            if (val1_next > val1_current) { direction1 = 1; }
            else if (val1_next < val1_current) { direction1 = 2; }

            let direction2: u32 = 0;
            if (val2_next > val2_current) { direction2 = 1; }
            else if (val2_next < val2_current) { direction2 = 2; }

            if (direction1 == direction2 && direction1 != 0) {
                same_direction = same_direction + 1;
            }

            i = i + 1;
        }

        // Return correlation strength
        if (count > 1) {
            return (same_direction * 100) / (count - 1);
        } else {
            return 0;
        }
    }

    // Detect coordinated attack (multiple metrics anomalous)
    fn detect_coordinated_attack(anomalies: [u32; MAX_METRICS], count: u32) -> u32 {
        let critical_count: u32 = 0;
        let i: u32 = 0;

        while (i < count) {
            if (is_critical_anomaly(anomalies[i]) == 1) {
                critical_count = critical_count + 1;
            }
            i = i + 1;
        }

        // Coordinated if 2+ critical anomalies
        if (critical_count >= 2) {
            return 1;
        } else {
            return 0;
        }
    }

    // Calculate anomaly confidence
    fn calculate_anomaly_confidence(report: u32, historical_confidence: u32) -> u32 {
        let severity: u32 = get_severity(report);
        let base_confidence: u32 = get_anomaly_confidence(report);

        // Weight severity and historical accuracy
        let weighted_confidence: u32 = ((severity * 30) / 100) + 
                                        ((base_confidence * 50) / 100) + 
                                        ((historical_confidence * 20) / 100);

        if (weighted_confidence > 100) {
            return 100;
        } else {
            return weighted_confidence;
        }
    }

    // ---- Tests ----

    test metric_reading_roundtrip {
        r = create_metric_reading(7, 200, 99, 55);
        assert(get_metric_id(r) == 7, "metric id");
        assert(get_metric_value(r) == 200, "metric value");
        assert(get_timestamp(r) == 99, "timestamp");
        assert(get_confidence(r) == 55, "confidence");
    }

    test anomaly_report_roundtrip {
        rep = create_anomaly_report(9, 90, TYPE_PATTERN, 12345);
        assert(get_anomaly_metric_id(rep) == 9, "report metric id");
        assert(get_severity(rep) == 90, "severity");
        assert(get_anomaly_type(rep) == TYPE_PATTERN, "anomaly type");
        assert(get_anomaly_confidence(rep) == 12345, "report confidence");
    }

    test baseline_and_variance {
        // Eight readings with values 100 and 120 alternating: baseline 110,
        // mean absolute deviation 10.
        let h: [u32; 16] = [
            create_metric_reading(1, 100, 0, 50), create_metric_reading(1, 120, 1, 50),
            create_metric_reading(1, 100, 2, 50), create_metric_reading(1, 120, 3, 50),
            create_metric_reading(1, 100, 4, 50), create_metric_reading(1, 120, 5, 50),
            create_metric_reading(1, 100, 6, 50), create_metric_reading(1, 120, 7, 50),
            0, 0, 0, 0, 0, 0, 0, 0
        ];
        b = calculate_baseline(h, 8);
        assert(b == 110, "baseline is the mean");
        v = calculate_variance(h, 8, b);
        assert(v == 10, "variance is the mean absolute deviation");
    }

    test spike_and_drop_detection {
        // Variance 10 -> spike threshold is 3*10 above baseline 110.
        assert(detect_spike(150, 110, 10) == 1, "40 above baseline is a spike");
        assert(detect_spike(130, 110, 10) == 0, "20 above baseline is noise");
        assert(detect_drop(70, 110, 10) == 1, "40 below baseline is a drop");
        assert(detect_drop(95, 110, 10) == 0, "15 below baseline is noise");
    }

    test severity_bands {
        assert(calculate_severity(250, 100) == 90, "diff 150 is high severity");
        assert(calculate_severity(170, 100) == 60, "diff 70 is medium severity");
        assert(calculate_severity(120, 100) == 30, "diff 20 is low severity");
    }
}

// Docs Generator - multi-format documentation output generation
// Creates formatted documentation in various output formats

module docs_generator {
    use base::types;

    const MAX_SECTIONS: u32 = 16;
    const MAX_TABLES: u32 = 8;
    const MAX_REFERENCES: u32 = 32;
    const OUTPUT_BUFFER_SIZE: u32 = 4096;

    // Output format [format_id][version][compression][encoding]
    fn create_output_format(format_id: u32, version: u32, compression: u32, encoding: u32) -> u32 {
        return (((format_id & 0xF) << 28) |
                ((version & 0xFF) << 20) |
                ((compression & 0xF) << 16) |
                (encoding & 0xFFFF));
    }

    fn get_format_id(format: u32) -> u32 {
        return ((format >> 28) & 0xF);
    }

    fn get_format_version(format: u32) -> u32 {
        return ((format >> 20) & 0xFF);
    }

    fn get_format_compression(format: u32) -> u32 {
        return ((format >> 16) & 0xF);
    }

    fn get_format_encoding(format: u32) -> u32 {
        return (format & 0xFFFF);
    }

    // Format types
    const FORMAT_MARKDOWN: u32 = 0;
    const FORMAT_HTML: u32 = 1;
    const FORMAT_PDF: u32 = 2;
    const FORMAT_TEXT: u32 = 3;
    const FORMAT_JSON: u32 = 4;

    // Document section [section_id][level][content_length][subsection_count]
    fn create_document_section(section_id: u32, level: u32, content_len: u32, subsections: u32) -> u32 {
        return (((section_id & 0xFF) << 24) |
                ((level & 0xF) << 20) |
                ((content_len & 0xFF) << 12) |
                (subsections & 0xFFF));
    }

    fn get_section_id(section: u32) -> u32 {
        return ((section >> 24) & 0xFF);
    }

    fn get_section_level(section: u32) -> u32 {
        return ((section >> 20) & 0xF);
    }

    fn get_section_content_length(section: u32) -> u32 {
        return ((section >> 12) & 0xFF);
    }

    fn get_section_subsection_count(section: u32) -> u32 {
        return (section & 0xFFF);
    }

    // Create table of contents entry
    fn create_toc_entry(section_id: u32, level: u32, page_number: u32, title_id: u32) -> u32 {
        return (((section_id & 0xFF) << 24) |
                ((level & 0xF) << 20) |
                ((page_number & 0xFF) << 12) |
                (title_id & 0xFFF));
    }

    fn get_toc_section_id(toc: u32) -> u32 {
        return ((toc >> 24) & 0xFF);
    }

    fn get_toc_level(toc: u32) -> u32 {
        return ((toc >> 20) & 0xF);
    }

    fn get_toc_page_number(toc: u32) -> u32 {
        return ((toc >> 12) & 0xFF);
    }

    fn get_toc_title_id(toc: u32) -> u32 {
        return (toc & 0xFFF);
    }

    // Generate Markdown header
    fn generate_markdown_header(level: u32, title_id: u32) -> u32 {
        // Markdown uses # for headers, ## for subsections, etc.
        let header_prefix: u32 = 0;
        if (level == 1) {
            header_prefix = 0x23; // '#'
        } else if (level == 2) {
            header_prefix = 0x2323; // '##'
        } else if (level == 3) {
            header_prefix = 0x232323; // '###'
        }

        return (((header_prefix & 0xFFFFFF) << 8) | (title_id & 0xFF));
    }

    // Generate HTML tag
    fn generate_html_tag(tag_type: u32, content_id: u32, attributes: u32) -> u32 {
        return (((tag_type & 0xFF) << 24) |
                ((content_id & 0xFF) << 16) |
                (attributes & 0xFFFF));
    }

    fn get_html_tag_type(tag: u32) -> u32 {
        return ((tag >> 24) & 0xFF);
    }

    fn get_html_content_id(tag: u32) -> u32 {
        return ((tag >> 16) & 0xFF);
    }

    fn get_html_attributes(tag: u32) -> u32 {
        return (tag & 0xFFFF);
    }

    // HTML tag types
    const TAG_H1: u32 = 1;
    const TAG_H2: u32 = 2;
    const TAG_H3: u32 = 3;
    const TAG_P: u32 = 4;
    const TAG_TABLE: u32 = 5;
    const TAG_DIV: u32 = 6;

    // Create reference link
    fn create_reference_link(source_id: u32, target_id: u32, link_type: u32, anchor: u32) -> u32 {
        return (((source_id & 0xFF) << 24) |
                ((target_id & 0xFF) << 16) |
                ((link_type & 0xF) << 12) |
                (anchor & 0xFFF));
    }

    fn get_ref_source(link: u32) -> u32 {
        return ((link >> 24) & 0xFF);
    }

    fn get_ref_target(link: u32) -> u32 {
        return ((link >> 16) & 0xFF);
    }

    fn get_ref_type(link: u32) -> u32 {
        return ((link >> 12) & 0xF);
    }

    fn get_ref_anchor(link: u32) -> u32 {
        return (link & 0xFFF);
    }

    // Link types
    const LINK_INTERNAL: u32 = 0;
    const LINK_EXTERNAL: u32 = 1;
    const LINK_API: u32 = 2;
    const LINK_EXAMPLE: u32 = 3;

    // Format code block
    fn format_code_block(language: u32, code_id: u32, line_count: u32) -> u32 {
        return (((language & 0xFF) << 24) |
                ((code_id & 0xFF) << 16) |
                (line_count & 0xFFFF));
    }

    fn get_code_block_language(block: u32) -> u32 {
        return ((block >> 24) & 0xFF);
    }

    fn get_code_block_code_id(block: u32) -> u32 {
        return ((block >> 16) & 0xFF);
    }

    fn get_code_block_line_count(block: u32) -> u32 {
        return (block & 0xFFFF);
    }

    // Create data table
    fn create_data_table(table_id: u32, row_count: u32, col_count: u32, header_count: u32) -> u32 {
        return (((table_id & 0xFF) << 24) |
                ((row_count & 0xFF) << 16) |
                ((col_count & 0xFF) << 8) |
                (header_count & 0xFF));
    }

    fn get_table_id(table: u32) -> u32 {
        return ((table >> 24) & 0xFF);
    }

    fn get_table_row_count(table: u32) -> u32 {
        return ((table >> 16) & 0xFF);
    }

    fn get_table_col_count(table: u32) -> u32 {
        return ((table >> 8) & 0xFF);
    }

    fn get_table_header_count(table: u32) -> u32 {
        return (table & 0xFF);
    }

    // Generate table row
    fn generate_table_row(table_id: u32, row_index: u32, data_start: u32, data_count: u32) -> u32 {
        return (((table_id & 0xFF) << 24) |
                ((row_index & 0xFF) << 16) |
                ((data_start & 0xFF) << 8) |
                (data_count & 0xFF));
    }

    // Create index entry
    fn create_index_entry(term_id: u32, location: u32, frequency: u32, importance: u32) -> u32 {
        return (((term_id & 0xFF) << 24) |
                ((location & 0xFF) << 16) |
                ((frequency & 0xFF) << 8) |
                (importance & 0xFF));
    }

    fn get_index_term_id(entry: u32) -> u32 {
        return ((entry >> 24) & 0xFF);
    }

    fn get_index_location(entry: u32) -> u32 {
        return ((entry >> 16) & 0xFF);
    }

    fn get_index_frequency(entry: u32) -> u32 {
        return ((entry >> 8) & 0xFF);
    }

    fn get_index_importance(entry: u32) -> u32 {
        return (entry & 0xFF);
    }

    // Generate page layout
    fn generate_page_layout(margin_top: u32, margin_bottom: u32, margin_left: u32, margin_right: u32) -> u32 {
        return (((margin_top & 0xFF) << 24) |
                ((margin_bottom & 0xFF) << 16) |
                ((margin_left & 0xFF) << 8) |
                (margin_right & 0xFF));
    }

    fn get_margin_top(layout: u32) -> u32 {
        return ((layout >> 24) & 0xFF);
    }

    fn get_margin_bottom(layout: u32) -> u32 {
        return ((layout >> 16) & 0xFF);
    }

    fn get_margin_left(layout: u32) -> u32 {
        return ((layout >> 8) & 0xFF);
    }

    fn get_margin_right(layout: u32) -> u32 {
        return (layout & 0xFF);
    }

    // Calculate document statistics
    fn calculate_document_stats(sections: [u32; MAX_SECTIONS], section_count: u32) -> u32 {
        let total_pages: u32 = 0;
        let total_words: u32 = 0;
        let total_tables: u32 = 0;
        let total_figures: u32 = 0;
        let i: u32 = 0;

        while (i < section_count) {
            let content_len: u32 = get_section_content_length(sections[i]);
            let subsections: u32 = get_section_subsection_count(sections[i]);

            total_words = total_words + (content_len / 5); // Assume 5 chars per word
            total_pages = total_pages + (content_len / 300); // Assume 300 words per page

            if (subsections > 0) {
                total_tables = total_tables + 1;
            }

            i = i + 1;
        }

        // Return stats: [total_pages][total_words][total_tables][total_figures]
        return (((total_pages & 0xFF) << 24) |
                ((total_words & 0xFF) << 16) |
                ((total_tables & 0xFF) << 8) |
                (total_figures & 0xFF));
    }

    // Generate document metadata
    fn generate_document_metadata(title_id: u32, author_id: u32, date: u32, version: u32) -> u32 {
        return (((title_id & 0xFF) << 24) |
                ((author_id & 0xFF) << 16) |
                ((date & 0xFF) << 8) |
                (version & 0xFF));
    }

    fn get_metadata_title(metadata: u32) -> u32 {
        return ((metadata >> 24) & 0xFF);
    }

    fn get_metadata_author(metadata: u32) -> u32 {
        return ((metadata >> 16) & 0xFF);
    }

    fn get_metadata_date(metadata: u32) -> u32 {
        return ((metadata >> 8) & 0xFF);
    }

    fn get_metadata_version(metadata: u32) -> u32 {
        return (metadata & 0xFF);
    }

    // Format document for output
    fn format_document(sections: [u32; MAX_SECTIONS], section_count: u32, 
                       format: u32, layout: u32) -> u32 {
        let formatted_size: u32 = 0;
        let i: u32 = 0;

        while (i < section_count) {
            let content_len: u32 = get_section_content_length(sections[i]);
            formatted_size = formatted_size + content_len;
            i = i + 1;
        }

        // Add layout overhead
        let margin_overhead: u32 = get_margin_top(layout) + get_margin_bottom(layout);
        formatted_size = formatted_size + margin_overhead;

        let format_id: u32 = get_format_id(format);

        // Format-specific size adjustments
        if (format_id == FORMAT_HTML) {
            formatted_size = formatted_size + (section_count * 20); // HTML tags
        } else if (format_id == FORMAT_MARKDOWN) {
            formatted_size = formatted_size + (section_count * 5); // Markdown formatting
        }

        return formatted_size;
    }

    // Generate complete documentation
    fn generate_complete_document(func_docs: [u32; 64], func_count: u32,
                                  sections: [u32; MAX_SECTIONS], section_count: u32,
                                  format: u32) -> u32 {
        let metadata: u32 = generate_document_metadata(1, 1, 20260703, 1);
        let layout: u32 = generate_page_layout(20, 20, 15, 15);

        let toc_size: u32 = section_count * 10;
        let body_size: u32 = format_document(sections, section_count, format, layout);
        let index_size: u32 = func_count * 5;

        let total_size: u32 = toc_size + body_size + index_size;

        // Return document info: [total_size][section_count][func_count][format_id]
        return (((total_size & 0xFFFF) << 16) |
                ((section_count & 0xFF) << 8) |
                ((func_count & 0xFF)));
    }

    // Validate generated documentation
    fn validate_documentation(generated_doc: u32, expected_sections: u32, expected_funcs: u32) -> u32 {
        let actual_sections: u32 = (generated_doc >> 8) & 0xFF;
        let actual_funcs: u32 = generated_doc & 0xFF;

        let section_match: u32 = 0;
        let func_match: u32 = 0;

        if (actual_sections >= expected_sections) {
            section_match = 1;
        }

        if (actual_funcs >= expected_funcs) {
            func_match = 1;
        }

        // Return validation: [section_match][func_match][quality_score][completeness]
        let quality_score: u32 = (section_match * 50) + (func_match * 50);
        let completeness: u32 = ((actual_sections * 10) / expected_sections) * 10;

        return (((section_match & 0x1) << 15) |
                ((func_match & 0x1) << 14) |
                ((quality_score & 0xFF) << 8) |
                (completeness & 0xFF));
    }

    // ---- Tests ----

    test output_format_roundtrip {
        f = create_output_format(9, 200, 5, 50000);
        assert(get_format_id(f) == 9, "format id");
        assert(get_format_version(f) == 200, "version");
        assert(get_format_compression(f) == 5, "compression");
        assert(get_format_encoding(f) == 50000, "encoding");
    }

    test markdown_header_levels {
        h1 = generate_markdown_header(1, 7);
        assert(((h1 >> 8) & 0xFFFFFF) == 0x23, "level 1 prefix");
        assert((h1 & 0xFF) == 7, "title id");
        h3 = generate_markdown_header(3, 7);
        assert(((h3 >> 8) & 0xFFFFFF) == 0x232323, "level 3 prefix");
    }
}

// Key Management - lightweight key rotation and distribution
// Simplified alternative to complex PKI for mesh networks

module KeyManagement {
    use base::types;

    const MAX_KEYS: u32 = 4;
    const KEY_SIZE: u32 = 4; // 32-bit keys (simplified)
    const KEY_VALID: u32 = 1;
    const KEY_INVALID: u32 = 0;
    const ROTATION_INTERVAL: u32 = 30000; // 30 seconds

    // Key entry [valid][key_id][key_value][timestamp]
    // Layout [valid:1][key_id:7][key_value:16][timestamp:8] = exactly 32.
    // The old layout gave key_id 8 bits at 24..31 UNDER the valid bit at 31:
    // a set valid bit read back as key_id | 0x80.
    fn create_key_entry(valid: u32, key_id: u32, key_value: u32, timestamp: u32) -> u32 {
        return (((valid & 0x1) << 31) |
                ((key_id & 0x7F) << 24) |
                ((key_value & 0xFFFF) << 8) |
                (timestamp & 0xFF));
    }

    fn get_key_valid(entry: u32) -> u32 {
        return ((entry >> 31) & 0x1);
    }

    fn get_key_id(entry: u32) -> u32 {
        return ((entry >> 24) & 0x7F);
    }

    fn get_key_value(entry: u32) -> u32 {
        return ((entry >> 8) & 0xFFFF);
    }

    fn get_key_timestamp(entry: u32) -> u32 {
        return (entry & 0xFF);
    }

    // 4-key storage
    // Four 32-bit entries need 128 bits: the old u64 packing at 16-bit
    // strides made every 32-bit read overlap its neighbors. A real array.
    fn create_key_store(k0: u32, k1: u32, k2: u32, k3: u32) -> [u32; 4] {
        return [k0, k1, k2, k3];
    }

    fn set_key_slot(store: [u32; 4], index: u32, entry: u32) -> [u32; 4] {
        // Locals, not store[i], inside the literal: the parser cuts the
        // element text at the first ']'.
        let k0: u32 = store[0];
        let k1: u32 = store[1];
        let k2: u32 = store[2];
        let k3: u32 = store[3];
        if (index == 0) { return [entry, k1, k2, k3]; }
        if (index == 1) { return [k0, entry, k2, k3]; }
        if (index == 2) { return [k0, k1, entry, k3]; }
        return [k0, k1, k2, entry];
    }

    fn get_key_entry(store: [u32; 4], index: u32) -> u32 {
        if (index < 4) {
            return store[index];
        }
        return 0;
    }

    // Find key by ID
    fn find_key_by_id(store: [u32; 4], key_id: u32) -> u32 {
        if (get_key_id(get_key_entry(store, 0)) == key_id && get_key_valid(get_key_entry(store, 0)) == KEY_VALID) {
            return 0;
        } else if (get_key_id(get_key_entry(store, 1)) == key_id && get_key_valid(get_key_entry(store, 1)) == KEY_VALID) {
            return 1;
        } else if (get_key_id(get_key_entry(store, 2)) == key_id && get_key_valid(get_key_entry(store, 2)) == KEY_VALID) {
            return 2;
        } else if (get_key_id(get_key_entry(store, 3)) == key_id && get_key_valid(get_key_entry(store, 3)) == KEY_VALID) {
            return 3;
        }
        return 0xFF; // Not found
    }

    // Add new key
    fn add_key(store: [u32; 4], key_id: u32, key_value: u32, timestamp: u32) -> [u32; 4] {
        // Find first empty slot
        if (get_key_valid(get_key_entry(store, 0)) == KEY_INVALID) {
            return set_key_slot(store, 0, create_key_entry(KEY_VALID, key_id, key_value, timestamp));
        } else if (get_key_valid(get_key_entry(store, 1)) == KEY_INVALID) {
            return set_key_slot(store, 1, create_key_entry(KEY_VALID, key_id, key_value, timestamp));
        } else if (get_key_valid(get_key_entry(store, 2)) == KEY_INVALID) {
            return set_key_slot(store, 2, create_key_entry(KEY_VALID, key_id, key_value, timestamp));
        } else if (get_key_valid(get_key_entry(store, 3)) == KEY_INVALID) {
            return set_key_slot(store, 3, create_key_entry(KEY_VALID, key_id, key_value, timestamp));
        }
        return store; // Key store full
    }

    // Invalidate key
    fn invalidate_key(store: [u32; 4], key_id: u32) -> [u32; 4] {
        let index = find_key_by_id(store, key_id);
        if (index != 0xFF) {
            let entry = get_key_entry(store, index);
            let new_entry = create_key_entry(KEY_INVALID, get_key_id(entry), get_key_value(entry), get_key_timestamp(entry));
            return set_key_slot(store, index, new_entry);
        }
        return store; // Key not found
    }

    // Check if key needs rotation
    fn needs_rotation(entry: u32, current_time: u32) -> bool {
        if (get_key_valid(entry) == KEY_INVALID) {
            return false; // Invalid keys don't need rotation
        }

        let age = current_time - get_key_timestamp(entry);
        return (age >= ROTATION_INTERVAL);
    }

    // Rotate key (generate new value)
    fn rotate_key(store: [u32; 4], key_id: u32, new_value: u32, current_time: u32) -> [u32; 4] {
        let index = find_key_by_id(store, key_id);
        if (index != 0xFF) {
            let new_entry = create_key_entry(KEY_VALID, key_id, new_value, current_time);
            return set_key_slot(store, index, new_entry);
        }
        return store; // Key not found
    }

    // Get active key (most recent)
    fn get_active_key(store: [u32; 4]) -> u32 {
        let best_index = 0xFF;
        let best_timestamp = 0;

        if (get_key_valid(get_key_entry(store, 0)) == KEY_VALID) {
            let ts = get_key_timestamp(get_key_entry(store, 0));
            if (ts >= best_timestamp) {
                best_timestamp = ts;
                best_index = 0;
            }
        }

        if (get_key_valid(get_key_entry(store, 1)) == KEY_VALID) {
            let ts = get_key_timestamp(get_key_entry(store, 1));
            if (ts >= best_timestamp) {
                best_timestamp = ts;
                best_index = 1;
            }
        }

        if (get_key_valid(get_key_entry(store, 2)) == KEY_VALID) {
            let ts = get_key_timestamp(get_key_entry(store, 2));
            if (ts >= best_timestamp) {
                best_timestamp = ts;
                best_index = 2;
            }
        }

        if (get_key_valid(get_key_entry(store, 3)) == KEY_VALID) {
            let ts = get_key_timestamp(get_key_entry(store, 3));
            if (ts >= best_timestamp) {
                best_timestamp = ts;
                best_index = 3;
            }
        }

        if (best_index != 0xFF) {
            return get_key_value(get_key_entry(store, best_index));
        }
        return 0; // No active key
    }

    // Count valid keys
    fn count_valid_keys(store: [u32; 4]) -> u32 {
        let count = 0;
        if (get_key_valid(get_key_entry(store, 0)) == KEY_VALID) { count = count + 1; }
        if (get_key_valid(get_key_entry(store, 1)) == KEY_VALID) { count = count + 1; }
        if (get_key_valid(get_key_entry(store, 2)) == KEY_VALID) { count = count + 1; }
        if (get_key_valid(get_key_entry(store, 3)) == KEY_VALID) { count = count + 1; }
        return count;
    }

    // ---- Tests ----

    test create_key_entry_basic {
        entry = create_key_entry(1, 5, 0xABCD, 100);
        assert(get_key_valid(entry) == 1, "valid");
        assert(get_key_id(entry) == 5, "id");
        assert(get_key_value(entry) == 0xABCD, "value");
        assert(get_key_timestamp(entry) == 100, "timestamp");
    }

    test find_key_by_id_found {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10),
            create_key_entry(1, 2, 0x2222, 20),
            create_key_entry(0, 3, 0x3333, 30),
            create_key_entry(1, 4, 0x4444, 40)
        );
        assert(find_key_by_id(store, 2) == 1, "found at index 1");
    }

    test find_key_by_id_not_found {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10),
            create_key_entry(1, 2, 0x2222, 20),
            create_key_entry(0, 3, 0x3333, 30),
            create_key_entry(1, 4, 0x4444, 40)
        );
        assert(find_key_by_id(store, 99) == 0xFF, "not found");
    }

    test find_key_by_id_invalid_ignored {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10),
            create_key_entry(0, 2, 0x2222, 20),
            create_key_entry(1, 3, 0x3333, 30),
            create_key_entry(1, 4, 0x4444, 40)
        );
        assert(find_key_by_id(store, 2) == 0xFF, "invalid key ignored");
    }

    test add_key_empty_slot {
        store = create_key_store(
            create_key_entry(0, 0, 0, 0),
            create_key_entry(0, 0, 0, 0),
            create_key_entry(0, 0, 0, 0),
            create_key_entry(0, 0, 0, 0)
        );
        new_store = add_key(store, 5, 0xABCD, 100);
        assert(get_key_id(get_key_entry(new_store, 0)) == 5, "key added");
    }

    test invalidate_key_works {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10),
            create_key_entry(1, 2, 0x2222, 20),
            create_key_entry(1, 3, 0x3333, 30),
            create_key_entry(0, 0, 0, 0)
        );
        new_store = invalidate_key(store, 2);
        assert(get_key_valid(get_key_entry(new_store, 1)) == 0, "key invalidated");
    }

    test needs_rotation_true {
        entry = create_key_entry(1, 1, 0x1111, 1000);
        assert(needs_rotation(entry, 35000) == true, "needs rotation");
    }

    test needs_rotation_false {
        entry = create_key_entry(1, 1, 0x1111, 25000);
        assert(needs_rotation(entry, 30000) == false, "no rotation needed");
    }

    test needs_rotation_invalid {
        entry = create_key_entry(0, 1, 0x1111, 1000);
        assert(needs_rotation(entry, 35000) == false, "invalid key");
    }

    test rotate_key_works {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10000),
            create_key_entry(0, 0, 0, 0),
            create_key_entry(0, 0, 0, 0),
            create_key_entry(0, 0, 0, 0)
        );
        new_store = rotate_key(store, 1, 0x9999, 50000);
        assert(get_key_value(get_key_entry(new_store, 0)) == 0x9999, "value updated");
    }

    test get_active_key_returns_latest {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10),
            create_key_entry(1, 2, 0x2222, 30),  // Latest
            create_key_entry(1, 3, 0x3333, 20),
            create_key_entry(0, 0, 0, 0)
        );
        assert(get_active_key(store) == 0x2222, "latest key");
    }

    test count_valid_keys_all {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10),
            create_key_entry(1, 2, 0x2222, 20),
            create_key_entry(1, 3, 0x3333, 30),
            create_key_entry(1, 4, 0x4444, 40)
        );
        assert(count_valid_keys(store) == 4, "4 valid keys");
    }

    test count_valid_keys_some {
        store = create_key_store(
            create_key_entry(1, 1, 0x1111, 10),
            create_key_entry(0, 2, 0x2222, 20),
            create_key_entry(1, 3, 0x3333, 30),
            create_key_entry(0, 4, 0x4444, 40)
        );
        assert(count_valid_keys(store) == 2, "2 valid keys");
    }
}

// TRI-NET DePIN settlement aggregator -- turns per-epoch Proof-of-Relay receipts
// (from tri_depin) into a node's $TRI reward for a payout round. A round is a set
// of epochs; each node's verified total_bytes are summed, and the round's token
// pool is split proportionally to metered bytes. Pure arithmetic, verifiable, so a
// settlement contract (or any auditor) can recompute every payout.

module TriSettle {
    use base::types;

    const PPM: u32 = 1000000; // parts-per-million fixed-point for shares
    const SNR_FLOOR: u32 = 3;  // dB below which a link is too weak to earn
    const SNR_CEIL:  u32 = 40; // dB above which link quality saturates

    // Fold one epoch's verified byte count into the running round total.
    // Saturating so an overflow can never wrap the round total DOWNWARD.
    fn round_add(round_total: u32, epoch_bytes: u32) -> u32 {
        let sum: u32 = round_total +% epoch_bytes;
        if (sum < round_total) {
            return 0xFFFFFFFF; // saturate
        } else {
            return sum;
        }
    }

    // A node's share of the round, in parts-per-million. Zero-guarded so an empty
    // round (no bytes relayed by anyone) pays nobody instead of dividing by zero.
    fn reward_share_ppm(node_bytes: u32, round_bytes: u32) -> u32 {
        if (round_bytes == 0) {
            return 0;
        } else {
            let scaled: u64 = (node_bytes as u64) * (PPM as u64);
            return (scaled / (round_bytes as u64)) as u32;
        }
    }

    // A node's actual token units from a round pool, = pool * node_bytes / round_bytes.
    // u64 intermediate avoids overflow; floor division means the sum of all nodes'
    // units never exceeds the pool (no over-issuance). Zero-guarded.
    fn reward_units(node_bytes: u32, round_bytes: u32, pool: u32) -> u64 {
        if (round_bytes == 0) {
            return 0;
        } else {
            let num: u64 = (pool as u64) * (node_bytes as u64);
            return num / (round_bytes as u64);
        }
    }

    // ---- Tests / invariants ----

    // Proportionality: twice the bytes -> twice the share.
    test share_proportional {
        half    = reward_share_ppm(100, 200);
        quarter = reward_share_ppm(50, 200);
        assert(half == 500000, "half");
        assert(quarter == 250000, "quarter");
        assert(half == quarter + quarter, "2x bytes = 2x share");
    }

    // A node that relayed the whole round gets the whole share.
    test share_full {
        assert(reward_share_ppm(200, 200) == PPM, "full share");
    }

    // Empty round / zero node -> zero share, no divide-by-zero.
    test share_zero_guard {
        assert(reward_share_ppm(5, 0) == 0, "empty round pays nobody");
        assert(reward_share_ppm(0, 200) == 0, "no work no share");
    }

    // No free mint: a node that relayed nothing earns nothing.
    test units_no_free_mint {
        assert(reward_units(0, 200, 1000) == 0, "no free mint");
    }

    // Proportional units from a pool.
    test units_proportional {
        assert(reward_units(100, 200, 1000) == 500, "half of pool");
    }

    // Conservation: with floor division, the sum of all nodes' units never exceeds
    // the pool (the protocol can never issue more than the round's pool).
    test units_conservation {
        a = reward_units(100, 300, 1000); // 333
        b = reward_units(200, 300, 1000); // 666
        assert(a == 333, "node a");
        assert(b == 666, "node b");
        assert(a + b <= (1000 as u64), "sum <= pool");
    }

    // Round accumulation grows monotonically and saturates.
    test round_monotonic {
        r0 = round_add(0, 19974);
        r1 = round_add(r0, 40000);
        assert(r1 > r0, "monotonic");
        assert(r0 == 19974, "epoch1");
        assert(r1 == 59974, "epoch1+2");
    }

    test round_saturates {
        assert(round_add(0xFFFFFF00, 0x0000FFFF) == 0xFFFFFFFF, "saturates");
    }

    // ---- Link-quality-weighted reward (Helium-class Proof-of-Coverage, WAVE d) ----
    // Flat proportional-to-bytes pays a node on a terrible link the same per byte as
    // one on a great link -- so nobody is rewarded for extending good coverage. Weight
    // each node's contribution by a link-quality score (derived from the measured SNR:
    // e.g. quality = clamp(SNR_dB) so 47 dB -> high, 3 dB -> low). Effective
    // contribution = bytes * quality; the pool is split by weighted contribution.

    // One node's weighted contribution to the round (u64 to hold bytes*quality).
    fn weighted_contrib(node_bytes: u32, quality: u32) -> u64 {
        return (node_bytes as u64) * (quality as u64);
    }

    // Fold a node's weighted contribution into the round's weighted total.
    fn round_add_weighted(wtotal: u64, node_bytes: u32, quality: u32) -> u64 {
        return wtotal + weighted_contrib(node_bytes, quality);
    }

    // A node's token units = pool * (bytes*quality) / weighted_total. Two-stage
    // scaling (ppm first) keeps every intermediate inside u64. Zero-guarded; floor
    // division keeps the sum of all nodes' units within the pool.
    fn reward_weighted(node_bytes: u32, quality: u32, weighted_total: u64, pool: u32) -> u64 {
        // t27c codegen narrows a `u64 == <lit>` compare to u32, so a plain
        // `weighted_total == 0` would read any 2^32 multiple as zero. Test both u32
        // halves explicitly instead. (Compiler bug logged for the t27 repo.)
        let hi: u32 = (weighted_total >> 32) as u32;
        let lo: u32 = weighted_total as u32;
        if ((hi == 0) && (lo == 0)) {
            return 0;
        } else {
            let contrib: u64 = (node_bytes as u64) * (quality as u64);
            let ppm: u64 = (contrib * 1000000) / weighted_total;
            return ((pool as u64) * ppm) / 1000000;
        }
    }

    // A better link earns more from the SAME bytes.
    test weighted_quality_rewards_coverage {
        // node A: 1000 bytes @ quality 47 (47 dB link, ours); node B: 1000 bytes @ 10
        wt = round_add_weighted(round_add_weighted(0, 1000, 47), 1000, 10);
        a = reward_weighted(1000, 47, wt, 1000);
        b = reward_weighted(1000, 10, wt, 1000);
        assert(a > b, "better link earns more per byte");
        assert(wt == (57000 as u64), "weighted total = 47000 + 10000");
    }

    // Equal quality collapses to flat proportional-by-bytes.
    test weighted_equal_quality_is_proportional {
        wt = round_add_weighted(round_add_weighted(0, 100, 5), 200, 5);
        a = reward_weighted(100, 5, wt, 1000); // 100/300 of pool
        b = reward_weighted(200, 5, wt, 1000); // 200/300 of pool
        assert(a == 333, "third");
        assert(b == 666, "two thirds");
    }

    // Conservation: weighted units never exceed the pool.
    test weighted_conservation {
        wt = round_add_weighted(round_add_weighted(0, 1000, 47), 500, 30);
        a = reward_weighted(1000, 47, wt, 10000);
        b = reward_weighted(500, 30, wt, 10000);
        assert(a + b <= (10000 as u64), "sum <= pool");
    }

    // No free mint: zero quality (dead link) earns nothing.
    test weighted_zero_quality {
        wt = round_add_weighted(0, 1000, 47);
        assert(reward_weighted(1000, 0, wt, 1000) == 0, "dead link no reward");
    }

    // Large weighted total that is a 2^32 multiple must NOT be misread as zero
    // (guards against a narrowing u64->u32 compare in the zero check): 2^32 as u32 = 0.
    test weighted_large_total_not_zero {
        big = (4294967296 as u64);                    // 2^32; as u32 this would be 0
        r = reward_weighted(1000000, 1000, big, 1000); // contrib=1e9 -> ~232 units
        assert(r > (0 as u64), "large total not read as zero");
    }

    // ---- SNR -> link-quality mapping (measured on hardware; WAVE f) ----
    // Turn a node's measured link SNR (dB) into the quality weight reward_weighted
    // uses. A link below the floor is too weak to be worth paying for (dead -> 0);
    // above the ceiling it saturates. Piecewise-linear in dB, integer, monotone.
    // Measured on .13->.12: strong link 34 dB -> 31, weak link 5 dB -> 2.

    // snr_db is the measured SNR in dB, ALREADY CLAMPED to >= 0 by the caller (a
    // negative-SNR link is below the floor and clamps to 0 -> quality 0). Kept
    // unsigned on purpose: t27c narrows a signed `i32 <=` compare to u32, which would
    // read a negative dB as a huge value and pay a dead link. (t27c bug, same family
    // as the u64==0 narrowing; logged.)
    fn snr_to_quality(snr_db: u32) -> u32 {
        if (snr_db <= SNR_FLOOR) {
            return 0;
        } else if (snr_db >= SNR_CEIL) {
            return SNR_CEIL - SNR_FLOOR;
        } else {
            return snr_db - SNR_FLOOR;
        }
    }

    // A link at or below the floor earns nothing (matches "dead link no reward").
    test snr_quality_floor {
        assert(snr_to_quality(1) == 0, "1 dB unusable");
        assert(snr_to_quality(3) == 0, "at floor unusable");
    }

    // The two real measured links: strong 34 dB and weak 5 dB.
    test snr_quality_measured {
        assert(snr_to_quality(34) == 31, "strong link (.13->.12 -10 dB)");
        assert(snr_to_quality(5) == 2, "weak link (.13->.12 -50 dB)");
        assert(snr_to_quality(34) > snr_to_quality(5), "stronger link -> higher quality");
    }

    // Saturates above the ceiling (no unbounded reward for an extreme SNR).
    test snr_quality_ceiling {
        assert(snr_to_quality(100) == 37, "saturates at CEIL-FLOOR");
        assert(snr_to_quality(40) == 37, "at ceiling");
    }

    // End-to-end: the strong-coverage node out-earns the weak one for the SAME bytes.
    test snr_drives_reward {
        qa = snr_to_quality(34);
        qb = snr_to_quality(5);
        wt = round_add_weighted(round_add_weighted(0, 10000, qa), 10000, qb);
        ra = reward_weighted(10000, qa, wt, 1000);
        rb = reward_weighted(10000, qb, wt, 1000);
        assert(ra > rb, "better coverage earns more $TRI");
    }
}

