// RTI Security — passive perimeter monitoring via mesh RSSI
// Variant C: commercial security system, no cameras, AI classification
// phi^2 + phi^-2 = 3

module RTISecurity {
    use base::types;

    // ---- Zone parameters ----
    const MAX_ZONES: u8 = 16;
    const ZONE_GRID: u8 = 40;
    const ALERT_COOLDOWN_MS: u16 = 5000;  // 5s between alerts
    const SENSITIVITY_LOW: u8 = 1;
    const SENSITIVITY_MEDIUM: u8 = 2;
    const SENSITIVITY_HIGH: u8 = 3;

    // ---- Alert levels ----
    const ALERT_NONE: u8 = 0;
    const ALERT_INFO: u8 = 1;       // small movement
    const ALERT_WARNING: u8 = 2;   // suspicious activity
    const ALERT_CRITICAL: u8 = 3;  // intrusion detected
    const ALERT_TEST: u8 = 4;      // system test

    // ---- Alert entry (8 bytes) ----
    // [zone_id][level][x][y][confidence][size_cells][sensitivity][reserved]
    const ALERT_ENTRY_SIZE: u8 = 8;

    // ---- Zone definition ----
    // A zone is a rectangular area monitored for intrusion
    const ZONE_DEF_SIZE: u8 = 6;  // [zone_id][x1][y1][x2][y2][enabled]

    // Brightness threshold for a given sensitivity: day values, halved at night
    // (more sensitive in the dark). Early-return style: t27c-0.1.0 rejects any
    // reassignment of a typed local (I32-vs-U16 mismatch + immutability), so the
    // ladder is expressed as pure returns — the idiom every working spec uses.
    fn alert_threshold(sensitivity: u8, is_night: bool) -> u16 {
        if (is_night) {
            if (sensitivity == SENSITIVITY_HIGH) {
                return 20;
            }
            if (sensitivity == SENSITIVITY_LOW) {
                return 40;
            }
            return 30;
        }
        if (sensitivity == SENSITIVITY_HIGH) {
            return 40;
        }
        if (sensitivity == SENSITIVITY_LOW) {
            return 80;
        }
        return 60;
    }

    // Classify alert level from detection data
    fn classify_alert(brightness: u8, size_cells: u8, sensitivity: u8, is_night: bool) -> u8 {
        let threshold: u16 = alert_threshold(sensitivity, is_night);
        if (brightness < threshold) {
            return ALERT_NONE;
        }
        if (size_cells > 8) {
            return ALERT_CRITICAL;
        }
        if (size_cells > 4) {
            return ALERT_WARNING;
        }
        return ALERT_INFO;
    }

    // Is alert in cooldown period?
    fn in_cooldown(ms_since_last_alert: u16) -> bool {
        return ms_since_last_alert < ALERT_COOLDOWN_MS;
    }

    // Should we suppress this alert?
    fn should_suppress(level: u8, prev_level: u8, cooldown_ms: u16) -> bool {
        if (level == ALERT_NONE) {
            return true;
        }
        if (in_cooldown(cooldown_ms)) {
            if (level <= prev_level) {
                return true;  // same or lower level during cooldown
            }
        }
        return false;
    }

    // Zone ID from grid coordinates
    fn zone_from_coord(x: u8, y: u8, zone_size: u8) -> u8 {
        if (zone_size == 0) {
            return 0;
        }
        let zx: u8 = x / zone_size;
        let zy: u8 = y / zone_size;
        return zy * (ZONE_GRID / zone_size) + zx;
    }

    // Is point inside zone?
    fn in_zone(px: u8, py: u8, x1: u8, y1: u8, x2: u8, y2: u8) -> bool {
        if (px < x1) {
            return false;
        }
        if (px > x2) {
            return false;
        }
        if (py < y1) {
            return false;
        }
        if (py > y2) {
            return false;
        }
        return true;
    }

    // Threat score: combine alert level + size + confidence
    fn threat_score(level: u8, size: u8, confidence: u8) -> u16 {
        if (level == ALERT_NONE) {
            return 0;
        }
        let base: u16 = level as u16 * 100;
        let size_bonus: u16 = size as u16 * 10;
        let conf_bonus: u16 = confidence as u16;
        return base + size_bonus + conf_bonus;
    }

    // Escalation: should we upgrade alert?
    fn should_escalate(current: u8, accumulated_threat: u16) -> bool {
        if (current == ALERT_CRITICAL) {
            return false;  // already max
        }
        return accumulated_threat > 400;
    }

    // Night mode detection (hour-based)
    fn is_night_time(hour: u8) -> bool {
        if (hour < 6) {
            return true;   // 00:00-05:59
        }
        if (hour >= 22) {
            return true;   // 22:00-23:59
        }
        return false;
    }

    // Notification priority (for app push)
    fn notification_priority(level: u8) -> u8 {
        if (level == ALERT_CRITICAL) {
            return 10;  // immediate push
        }
        if (level == ALERT_WARNING) {
            return 5;   // batch push
        }
        return 1;       // log only
    }

    // ---- TDD ----

    test classify_none {
        assert(classify_alert(30, 3, SENSITIVITY_MEDIUM, false) == ALERT_NONE, "low brightness");
    }

    test classify_info {
        assert(classify_alert(70, 2, SENSITIVITY_MEDIUM, false) == ALERT_INFO, "small movement");
    }

    test classify_warning {
        assert(classify_alert(80, 5, SENSITIVITY_MEDIUM, false) == ALERT_WARNING, "medium object");
    }

    test classify_critical {
        assert(classify_alert(100, 10, SENSITIVITY_MEDIUM, false) == ALERT_CRITICAL, "large object");
    }

    test classify_night_sensitive {
        assert(classify_alert(35, 2, SENSITIVITY_MEDIUM, true) == ALERT_INFO, "night = more sensitive");
    }

    test classify_high_sensitivity {
        assert(classify_alert(45, 2, SENSITIVITY_HIGH, false) == ALERT_INFO, "high sens = lower threshold");
    }

    test in_cooldown_active {
        assert(in_cooldown(3000) == true, "3s < 5s cooldown");
    }

    test in_cooldown_expired {
        assert(in_cooldown(6000) == false, "6s > 5s cooldown");
    }

    test should_suppress_none {
        assert(should_suppress(ALERT_NONE, ALERT_NONE, 0) == true, "no alert = suppress");
    }

    test should_suppress_cooldown {
        assert(should_suppress(ALERT_INFO, ALERT_WARNING, 2000) == true, "lower during cooldown");
    }

    test should_not_suppress_higher {
        assert(should_suppress(ALERT_CRITICAL, ALERT_INFO, 2000) == false, "higher level passes");
    }

    test zone_from_coord_basic {
        assert(zone_from_coord(5, 5, 10) == 0, "top-left zone");
    }

    test zone_from_coord_second {
        assert(zone_from_coord(15, 5, 10) == 1, "second zone right");
    }

    test in_zone_inside {
        assert(in_zone(5, 5, 0, 0, 10, 10) == true, "inside");
    }

    test in_zone_outside_x {
        assert(in_zone(15, 5, 0, 0, 10, 10) == false, "outside X");
    }

    test in_zone_outside_y {
        assert(in_zone(5, 15, 0, 0, 10, 10) == false, "outside Y");
    }

    test threat_score_none {
        assert(threat_score(ALERT_NONE, 5, 100) == 0, "no alert = 0");
    }

    test threat_score_critical {
        assert(threat_score(ALERT_CRITICAL, 10, 200) == 600, "3*100 + 10*10 + 200");
    }

    test should_escalate_yes {
        assert(should_escalate(ALERT_INFO, 500) == true, "high threat");
    }

    test should_escalate_no {
        assert(should_escalate(ALERT_INFO, 100) == false, "low threat");
    }

    test is_night_late {
        assert(is_night_time(23) == true, "23:00 = night");
    }

    test is_night_early {
        assert(is_night_time(3) == true, "03:00 = night");
    }

    test is_day {
        assert(is_night_time(14) == false, "14:00 = day");
    }

    test notification_critical {
        assert(notification_priority(ALERT_CRITICAL) == 10, "immediate");
    }

    test notification_warning {
        assert(notification_priority(ALERT_WARNING) == 5, "batch");
    }

    test notification_info {
        assert(notification_priority(ALERT_INFO) == 1, "log only");
    }

    // ---- invariants ----

    invariant max_zones_16
        assert MAX_ZONES == 16

    invariant zone_grid_40
        assert ZONE_GRID == 40

    invariant alert_cooldown_5000
        assert ALERT_COOLDOWN_MS == 5000

    invariant alert_entry_8
        assert ALERT_ENTRY_SIZE == 8
}

// Hardware validation - bit-accurate simulation and board testing
// Tests hardware verification procedures

module HardwareValidation {
    use base::types;

    // Validation states
    const VAL_PENDING: u32 = 0;
    const VAL_RUNNING: u32 = 1;
    const VAL_PASSED: u32 = 2;
    const VAL_FAILED: u32 = 3;

    // Test types
    const TEST_SIMULATION: u32 = 1;
    const TEST_BIT_ACCURATE: u32 = 2;
    const TEST_FPGA_BOARD: u32 = 3;
    const TEST_REAL_WORLD: u32 = 4;

    // Test result (packed: [state:2][type:4][errors:10][iterations:16])
    fn create_test_result(state: u32, test_type: u32, errors: u32, iterations: u32) -> u32 {
        return (((state & 0x3) << 30) | 
                ((test_type & 0xF) << 26) | 
                ((errors & 0x3FF) << 16) | 
                (iterations & 0xFFFF));
    }

    fn extract_state(result: u32) -> u32 {
        return ((result >> 30) & 0x3);
    }

    fn extract_test_type(result: u32) -> u32 {
        return ((result >> 26) & 0xF);
    }

    fn extract_errors(result: u32) -> u32 {
        return ((result >> 16) & 0x3FF);
    }

    fn extract_iterations(result: u32) -> u32 {
        return (result & 0xFFFF);
    }

    // Calculate pass rate (percentage)
    fn calculate_pass_rate(passed: u32, total: u32) -> u8 {
        if (total == 0) {
            return 0;
        }
        return ((passed * 100) / total) as u8;
    }

    // Check if test passed (no errors)
    fn test_passed(result: u32) -> bool {
        return (extract_errors(result) == 0) && (extract_state(result) == VAL_PASSED);
    }

    // Check if bit-accurate (reference matches)
    fn bit_accurate(reference: u32, implementation: u32, tolerance_mask: u32) -> bool {
        // tolerance_mask marks bits ALLOWED to differ; accuracy requires all
        // bits OUTSIDE the mask to match. The old check tested the tolerated
        // bits themselves, failing exactly the differences it should permit.
        return (((reference ^ implementation) & (0xFFFFFFFF ^ tolerance_mask)) == 0);
    }

    // FPGA board test status
    fn fpga_board_ready(result: u32) -> bool {
        return (extract_state(result) == VAL_PASSED) && 
               (extract_test_type(result) == TEST_FPGA_BOARD);
    }

    // Real-world packet capture
    fn create_packet_capture(src: u32, dst: u32, payload: u32, timestamp: u32) -> u32 {
        // Simplified capture record
        return (((src & 0xFF) << 24) | 
                ((dst & 0xFF) << 16) | 
                ((payload & 0xFF) << 8) | 
                (timestamp & 0xFF));
    }

    fn extract_capture_src(capture: u32) -> u32 {
        return ((capture >> 24) & 0xFF);
    }

    fn extract_capture_dst(capture: u32) -> u32 {
        return ((capture >> 16) & 0xFF);
    }

    fn extract_capture_payload(capture: u32) -> u32 {
        return ((capture >> 8) & 0xFF);
    }

    fn extract_capture_timestamp(capture: u32) -> u32 {
        return (capture & 0xFF);
    }

    // Performance measurement
    // Layout [type:4][value:24][unit:4] = exactly 32. The old layout put
    // type at bit 24 UNDER the value field's top bits (4..27) -- the two
    // overlapped and corrupted each other.
    fn create_performance_metric(metric_type: u32, value: u32, unit: u32) -> u32 {
        return (((metric_type & 0xF) << 28) |
                ((value & 0xFFFFFF) << 4) |
                (unit & 0xF));
    }

    fn extract_metric_type(metric: u32) -> u32 {
        return ((metric >> 28) & 0xF);
    }

    fn extract_metric_value(metric: u32) -> u32 {
        return ((metric >> 4) & 0xFFFFFF);
    }

    fn extract_metric_unit(metric: u32) -> u32 {
        return (metric & 0xF);
    }

    // ---- Tests ----

    test create_test_result_correct {
        result = create_test_result(VAL_PASSED, TEST_SIMULATION, 0, 1000);
        assert(extract_state(result) == VAL_PASSED, "state");
        assert(extract_test_type(result) == TEST_SIMULATION, "type");
        assert(extract_errors(result) == 0, "errors");
        assert(extract_iterations(result) == 1000, "iterations");
    }

    test calculate_pass_rate_perfect {
        rate = calculate_pass_rate(100, 100);
        assert(rate == 100, "100% pass rate");
    }

    test calculate_pass_rate_half {
        rate = calculate_pass_rate(50, 100);
        assert(rate == 50, "50% pass rate");
    }

    test calculate_pass_rate_zero {
        rate = calculate_pass_rate(0, 100);
        assert(rate == 0, "0% pass rate");
    }

    test calculate_pass_rate_zero_total {
        rate = calculate_pass_rate(50, 0);
        assert(rate == 0, "zero total = 0%");
    }

    test test_passed_yes {
        result = create_test_result(VAL_PASSED, TEST_SIMULATION, 0, 100);
        assert(test_passed(result) == true, "no errors + passed state");
    }

    test test_passed_no_errors_but_pending {
        result = create_test_result(VAL_PENDING, TEST_SIMULATION, 0, 100);
        assert(test_passed(result) == false, "pending state");
    }

    test test_passed_errors {
        result = create_test_result(VAL_PASSED, TEST_SIMULATION, 5, 100);
        assert(test_passed(result) == false, "has errors");
    }

    test bit_accurate_exact_match {
        assert(bit_accurate(0x12345678, 0x12345678, 0xFFFFFFFF) == true, "exact match");
    }

    test bit_accurate_tolerance {
        assert(bit_accurate(0x12345678, 0x12345670, 0x000000FF) == true, "tolerance OK");
    }

    test bit_accurate_fail {
        assert(bit_accurate(0x12345678, 0x1234FF78, 0x000000FF) == false, "diff outside tolerated bits");
    }

    test fpga_board_ready_yes {
        result = create_test_result(VAL_PASSED, TEST_FPGA_BOARD, 0, 100);
        assert(fpga_board_ready(result) == true, "FPGA board ready");
    }

    test fpga_board_ready_no {
        result = create_test_result(VAL_PASSED, TEST_SIMULATION, 0, 100);
        assert(fpga_board_ready(result) == false, "not FPGA test");
    }

    test create_packet_capture_correct {
        capture = create_packet_capture(1, 2, 0xAB, 100);
        assert(extract_capture_src(capture) == 1, "src");
        assert(extract_capture_dst(capture) == 2, "dst");
        assert(extract_capture_payload(capture) == 0xAB, "payload");
        assert(extract_capture_timestamp(capture) == 100, "timestamp");
    }

    test create_performance_metric_correct {
        metric = create_performance_metric(5, 1000, 1);
        assert(extract_metric_type(metric) == 5, "type");
        assert(extract_metric_value(metric) == 1000, "value");
        assert(extract_metric_unit(metric) == 1, "unit");
    }

    test extract_metric_value_large {
        metric = create_performance_metric(3, 0xFFFFFF, 2);
        assert(extract_metric_value(metric) == 0xFFFFFF, "max value");
    }

    test extract_metric_type_boundary {
        metric = create_performance_metric(0xF, 1000, 0);
        assert(extract_metric_type(metric) == 0xF, "max type");
    }
}

// SPDX-License-Identifier: Apache-2.0
// specs/corona/protocol.t27
// Corona oracle protocol: 8-bit serial CMD/DATA on TinyTapeout pins.
// phi^2 + 1/phi^2 = 3 | TRINITY

// Status: [Spec]. The protocol is the read-back interface for the 80-record
// ROM and the encode/decode dispatch for Tier-1 modules.

module CoronaProtocol {
    use base::types;
    use corona::corona_oracle;
    use corona::rom_layout;

    // ========================================================================
    // 1. PIN BUDGET (TinyTapeout standard)
    // ========================================================================

    pub const N_UI_IN  : u8 = 8;   // input only
    pub const N_UO_OUT : u8 = 8;   // output only
    pub const N_UIO    : u8 = 8;   // bidirectional

    // When D2D is active:
    //   uio[3:0] -> inter-die TX
    //   uio[7:4] -> inter-die RX
    // Leaves all 8 ui_in, all 8 uo_out, and up to 4 spare uio bits for the
    // primary oracle interface.

    // ========================================================================
    // 2. PROTOCOL v2: TWO-BYTE CMD + RAW DATA
    // ========================================================================
    //
    // Protocol v2 eliminates the mode-field collision of v1. The mode field
    // ui_in[7:6] is inspected ONLY on the CMD1 cycle. All subsequent data
    // bytes are raw 8-bit (all 256 values valid).
    //
    // CMD1: ui_in[7]=0, ui_in[6:0] = fmt_id (0..76; 0x7F = anchor)
    // CMD2: ui_in[7:4] = reserved, ui_in[3:0] = byte_count (0..15)
    // DATA: byte_count cycles of raw 8-bit data on ui_in[7:0]
    // STATUS: auto-entered after last data byte; uo_out streams result
    //
    // In IDLE state, any byte with ui_in[7]=1 is ignored (no CMD).
    // This gives a clean separation: bit 7 = 0 means "this is a command".

    pub const CMD1_BIT7      : u1 = 0;   // CMD1 always has bit 7 = 0
    pub const MAX_BYTE_COUNT : u4 = 15;   // max data bytes per transaction

    // ========================================================================
    // 3. ANCHOR PROBE
    // ========================================================================

    // CMD1 with fmt_id = 0x7F produces {uio_out, uo_out} == 16'h47C0
    // combinationally (same cycle). This is the cross-die identity check.
    // No CMD2 or data phase is needed; the anchor response is immediate.
    pub const FMT_ID_ANCHOR : u8 = 0x7F;
    pub const ANCHOR_OUTPUT : u16 = 0x47C0;

    // ========================================================================
    // 4. CYCLE SEQUENCES (Protocol v2)
    // ========================================================================

    // 4.1 ROM record fetch (10 bytes per record).
    //   Cycle 1:   CMD1 = fmt_id
    //   Cycle 2:   CMD2 = byte_count=0 (no input data needed)
    //   Cycles 3..12: uo_out streams the 10 bytes of the record, LSB first.
    pub const CYCLES_ROM_FETCH : u8 = 12;

    // 4.2 8-bit format decode (e.g., posit8, mxfp8, lns8, bcd).
    //   Cycle 1:   CMD1 = fmt_id
    //   Cycle 2:   CMD2 = byte_count=1
    //   Cycle 3:   DATA = raw 8-bit input value (all 256 values valid)
    //   Cycles 4..7: uo_out streams 4 bytes of decoded FP32
    pub const CYCLES_DECODE_8 : u8 = 7;

    // 4.3 16-bit format decode (e.g., bf16).
    //   Cycle 1:   CMD1 = fmt_id
    //   Cycle 2:   CMD2 = byte_count=2
    //   Cycles 3..4: DATA = 2 raw bytes (LSB first)
    //   Cycles 5..8: uo_out streams 4 bytes of decoded FP32
    pub const CYCLES_DECODE_16 : u8 = 8;

    // 4.4 Sub-byte formats (fp4, fp6, nf4): byte_count=1, only lower bits used.
    //   Same as 4.2 but decoder reads only fp4_in[3:0] or fp6_in[5:0].
    pub const CYCLES_DECODE_SUB8 : u8 = 7;

    // ========================================================================
    // 5. UIO CONTROL ENCODING
    // ========================================================================

    // For multi-byte ROM record reads (field-select access):
    //   uio_in[3:0] = field selector (one of the 11 fields in rom_layout)
    //   uio_in[7:4] = cycle-within-field (for fields > 8 bits)
    //   uio_out[7]  = valid flag
    //   uio_out[6:0] = field-specific metadata

    // ========================================================================
    // 6. CONFORMANCE PROOF (PER FORMAT)
    // ========================================================================

    // Minimum conformance proof per Tier-1 format:
    //   encode(canonical_value, N) produces the expected bit pattern;
    //   decode(expected_bit_pattern, N) returns the canonical value
    //   within round-trip tolerance.
    //
    // Test vector counts:
    pub const VECTORS_PER_FORMAT_MIN     : u16 = 10;     // basic conformance
    pub const VECTORS_PER_FORMAT_ROBUST  : u16 = 50;     // robust conformance
    pub const VECTORS_PER_FORMAT_FULL    : u16 = 10000;  // CI module_roundtrip gate (Phase C)

    // ========================================================================
    // 7. NOT-IMPLEMENTED RESPONSE
    // ========================================================================

    // For Tier-2 ROM-only formats, a decode/encode query returns:
    //   uo_out byte 0 = 0xFF (sentinel)
    //   uo_out byte 1 = format_index (echo)
    //   uo_out byte 2 = status_id (echo from ROM)
    //   uo_out byte 3 = 0x4E (ASCII 'N' for Not-implemented)
    pub const NOT_IMPLEMENTED_SENTINEL : u8 = 0xFF;
    pub const NOT_IMPLEMENTED_TAG      : u8 = 0x4E;
}

// SPDX-License-Identifier: Apache-2.0
; 05 — Widths and casts, and the one that catches everybody
; Lesson 5. Converting between widths, and the single sharpest edge in the
; language today: an integer literal types as i32, so arithmetic on a narrower
; mutable local fails the type check unless you say what you mean.
; .
; Everything below is measured against the compiler in this repository, not
; guessed. The failing forms are written out as comments rather than as code,
; because a spec that does not compile teaches nothing.
; phi^2 + 1/phi^2 = 3 | TRINITY

module tutorial-05-widths;

// ============================================================================
// Casting
//
//   @as(TYPE, value)          assert a type
//   @intCast(value)           change integer width
//
// They are usually written together: @as names the destination, @intCast does
// the narrowing.
// ============================================================================

pub fn narrow(wide: u16) u8 {
    return @as(u8, @intCast(wide));
}

pub fn widen(small: u8) u16 {
    return @as(u16, small);
}

// ============================================================================
// The rule
//
// An integer literal is typed i32. So `x + 1` where x is an i8 is an i32
// expression, and assigning it back to an i8 is a type error.
//
// This does NOT compile -- do not copy it:
//
//     var x : i8 = a;
//     x = x + 1;              // type mismatch: cannot assign I32 to I8
//
// Nor does the compound form:
//
//     var x : i8 = a;
//     x += 1;                 // same mismatch
//
// It affects every width narrower than i32, signed or unsigned. At i32 and
// wider there is nothing to convert and the plain form is fine -- which is why
// lesson 04's loops all count in i32.
// ============================================================================

// ── Fix 1: say what you mean with a cast ────────────────────────────────────
pub fn increment_narrow(a: i8) i8 {
    var x : i8 = a;
    x = @as(i8, @intCast(x + 1));
    return x;
}

// ── Fix 2: don't mutate; bind a new value ───────────────────────────────────
// Usually the better answer. An immutable local sidesteps the assignment
// entirely, and the arithmetic still happens at i32 where it is safe.
pub fn increment_by_binding(a: i8) i8 {
    const stepped = a + 1;
    return @as(i8, @intCast(stepped));
}

// ── Fix 3: do the arithmetic wide, narrow once at the end ───────────────────
// The habit to build for anything with more than one step: stay at i32 while
// computing, convert once when you are done.
pub fn average_of_three(a: i8, b: i8, c: i8) i8 {
    const total : i32 = a + b + c;
    return @as(i8, @intCast(total / 3));
}

// ============================================================================
// The loop exception
//
// A `while` continue-expression accepts `i += 1` on a narrow counter, where
// the same statement in the body would not:
//
//     while (i < limit) : (i += 1) { ... }     // u8 counter: fine
//
// Worth knowing, but not worth relying on: the continue-expression is stored
// as text rather than as a node in the tree, so the type checker never sees
// it. It is not that this form is checked and passes -- it is that it is not
// checked at all. Prefer an i32 counter when the width is yours to choose.
// ============================================================================

pub fn sum_narrow_counter(limit: u8) u8 {
    var total : u8 = 0;
    var i : u8 = 0;
    while (i < limit) : (i += 1) {
        total = total + i;
    }
    return total;
}

// ============================================================================
// Tests
// ============================================================================

test "the three fixes agree with each other" {
    try std.testing.expectEqual(@as(i8, 4), increment_narrow(3));
    try std.testing.expectEqual(@as(i8, 4), increment_by_binding(3));
}

test "wide arithmetic then one narrowing" {
    try std.testing.expectEqual(@as(i8, 2), average_of_three(1, 2, 3));
}

test "narrowing keeps the low bits" {
    try std.testing.expectEqual(@as(u8, 0x34), narrow(0x1234));
    try std.testing.expectEqual(@as(u16, 7), widen(7));
}

// SPDX-License-Identifier: Apache-2.0
; 03 — Operators
; Lesson 3. Arithmetic, bitwise, shifts, comparison and the logical keywords.
; The bitwise group matters more here than in most languages: a spec that
; describes hardware spends most of its time on masks and shifts.
; phi^2 + 1/phi^2 = 3 | TRINITY

module tutorial-03-operators;

// ============================================================================
// Arithmetic
// ============================================================================

pub fn arithmetic(a: i32, b: i32) i32 {
    const sum = a + b;
    const difference = a - b;
    const product = a * b;
    const quotient = a / b;
    const remainder = a % b;
    return sum + difference + product + quotient + remainder;
}

// ============================================================================
// Bitwise
//
// `&` and, `|` or, `^` xor, `~` not. These are the tools for packing and
// unpacking fields, which is most of what a hardware spec does.
// ============================================================================

pub fn mask_and(value: u16, mask: u16) u16 {
    return value & mask;
}

pub fn mask_or(value: u16, bits: u16) u16 {
    return value | bits;
}

pub fn mask_xor(value: u16, bits: u16) u16 {
    return value ^ bits;
}

// ============================================================================
// Shifts
//
// `<<` and `>>`. Extracting a field is a shift followed by a mask, and that
// pair appears in nearly every numeric spec in this corpus.
// ============================================================================

pub const EXP_SHIFT : u16 = 9;
pub const EXP_MASK : u16 = 0b111111;

pub fn extract_exponent(bits: u16) u16 {
    return (bits >> EXP_SHIFT) & EXP_MASK;
}

pub fn place_exponent(exp: u16) u16 {
    return (exp & EXP_MASK) << EXP_SHIFT;
}

// ============================================================================
// Comparison
// ============================================================================

pub fn is_greater(a: i32, b: i32) bool {
    return a > b;
}

pub fn in_range(value: i32, low: i32, high: i32) bool {
    return value >= low and value <= high;
}

// ============================================================================
// Logical
//
// `and`, `or` and `!` are spelled as words rather than symbols, so they never
// read as their bitwise cousins.
// ============================================================================

pub fn either(a: bool, b: bool) bool {
    return a or b;
}

pub fn both(a: bool, b: bool) bool {
    return a and b;
}

pub fn neither(a: bool, b: bool) bool {
    return !a and !b;
}

// ============================================================================
// Tests
// ============================================================================

test "extract and place are inverse for a value that fits" {
    const exp : u16 = 42;
    try std.testing.expectEqual(exp, extract_exponent(place_exponent(exp)));
}

test "in_range is inclusive at both ends" {
    try std.testing.expect(in_range(0, 0, 10));
    try std.testing.expect(in_range(10, 0, 10));
    try std.testing.expect(!in_range(11, 0, 10));
}

test "neither is true only when both are false" {
    try std.testing.expect(neither(false, false));
    try std.testing.expect(!neither(true, false));
}
